CREATE TABLE IF NOT EXISTS episodes (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            broadcast   INTEGER,
            url         TEXT UNIQUE NOT NULL,
            title       TEXT,
            date        TEXT,
            scraped_at  TEXT DEFAULT (datetime('now'))
        );
