CREATE TABLE IF NOT EXISTS artist_enrichment (
    artist_name TEXT PRIMARY KEY,
    mbid TEXT,
    country TEXT,
    formed_year INTEGER,
    genres TEXT,
    tags TEXT,
    bio_summary TEXT,
    wikipedia_url TEXT,
    last_fetched TEXT,
    fetch_count INTEGER DEFAULT 1,
    canonical_name TEXT,
    lastfm_tags TEXT,
    lastfm_bio TEXT,
    lastfm_listeners TEXT,
    lastfm_playcount TEXT,
    lastfm_url TEXT
);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ramones', 'd6ed7887-a401-47a8-893c-34b967444d26', 'US', 1974, '[]', '["rock", "alternative rock", "punk", "american", "punk rock", "usa", "power pop", "pop-punk", "pop punk", "classic pop and rock", "rock & roll", "bubblegum", "new york punk", "permanent wave", "early us punk", "estados unidos"]', 'The Ramones were an American punk rock band formed in the New York City neighborhood Forest Hills, Queens in 1974. Known for helping establish the punk movement in the United States and elsewhere, the Ramones are often recognized as one of the first bands of the genre. Although they never achieved significant commercial success during their existence, the band is highly influential in punk culture.', 'https://en.wikipedia.org/wiki/Ramones', '2026-05-23 23:41:43', 35, 'Ramones', '["punk", "punk rock", "70s", "classic rock", "rock"]', 'Ramones were a punk band that formed in Queens, New York, United States, in 1974. They are often cited as the first punk group. Despite achieving only limited commercial success, the band was a major influence on the punk movement both in the United States and the United Kingdom.  All of the band members adopted pseudonyms ending with the surname "Ramone", though none of them were related. They performed 2,263 concerts, touring virtually nonstop for 22 years.', '2767529', '100528632', 'https://www.last.fm/music/Ramones');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Damned', '77d21c13-846f-4f48-9546-873949eff6ae', 'GB', 1976, '[]', '["rock", "pop", "progressive rock", "punk", "punk rock", "british", "seen live", "post-punk", "new wave", "uk", "deathrock", "gothic rock", "english", "england", "horror punk", "classic pop and rock", "proto-punk", "british punk", "alternative/indie rock", "dance-rock", "2008 universal fire victim"]', 'Damned or The Damned may refer to:', 'https://en.wikipedia.org/wiki/The_Damned', '2026-05-23 22:45:53', 241, 'The Damned', '["punk", "punk rock", "post-punk", "rock", "80s"]', 'The Damned are an English punk rock band formed in London in 1976 by lead vocalist Dave Vanian, guitarist Brian James, bassist (and later guitarist) Captain Sensible and drummer Rat Scabies. They were the first punk band from the United Kingdom to release a single, "New Rose" (1976), release a studio album, Damned Damned Damned (1977) and tour the United States. Nine of the band''s singles charted within the top 40 on the UK singles chart.  The band briefly dissolved after Music for Pleasure (1977)', '795561', '15343377', 'https://www.last.fm/music/The+Damned');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ween', 'c0eee88b-47f2-4cd2-ac48-a045e902a432', 'US', 1984, '[]', '["rock", "alternative rock", "american", "experimental", "indie", "funk rock", "alternative", "comedy", "lo-fi", "psychedelic rock", "hardcore punk", "art rock", "experimental rock", "pop rock", "neo-psychedelia", "comedy rock", "noise rock", "rock and indie", "lo-fi indie", "ween\u2039er\u203a", "weird america"]', 'Ween is an American rock band from New Hope, Pennsylvania, formed in 1984 by Aaron Freeman and Mickey Melchiondo, better known by their respective stage names, Gene Ween and Dean Ween. Generally categorized as an alternative rock band, the band are known for their irreverent, highly eclectic catalog of songs inspired by funk, psychedelia, soul, country, gospel, prog, R&B, heavy metal, and punk rock.', 'https://en.wikipedia.org/wiki/Ween', '2026-05-23 23:41:44', 25, 'Ween', '["experimental", "alternative", "rock", "indie", "alternative rock"]', 'Ween is an American rock band from New Hope, Pennsylvania, formed in 1984 by Aaron Freeman and Mickey Melchiondo, who perform under the stage names Gene Ween and Dean Ween. The band is commonly categorized as alternative rock and is noted for a highly eclectic musical style drawing on influences including funk, psychedelia, soul, country, gospel, progressive rock, R&B, heavy metal, and punk rock.  From their formation through 1989, Ween self-released several cassette-only recordings.', '1336294', '69759770', 'https://www.last.fm/music/Ween');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Continuals', '910590b6-0659-4cad-8136-ec5af43f79c5', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:51:55', 35, 'Continuals', '["washington dc", "USA", "rock", "indie", "indie rock"]', NULL, '1218', '8376', 'https://www.last.fm/music/Continuals');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Buzzcocks', '31e9c35b-2675-4632-8596-f9bd9286f6c8', 'GB', 1976, '[]', '["rock", "punk", "punk rock", "british", "post-punk", "new wave", "uk", "indie rock", "power pop", "pop punk", "english", "england", "classic pop and rock", "c81"]', 'Buzzcocks are an English punk rock band formed by singer-songwriter and guitarist Pete Shelley and singer-songwriter Howard Devoto in Bolton in 1976. They achieved commercial success with singles that fuse pop with rapid-fire punk energy, inspiring the power pop and pop punk movements; these singles were later collected on Singles Going Steady, an acclaimed compilation album music journalist and critic Ned Raggett described as a "punk masterpiece".', 'https://en.wikipedia.org/wiki/Buzzcocks', '2026-05-23 23:38:24', 216, 'Buzzcocks', '["punk", "punk rock", "british", "new wave", "rock"]', 'Buzzcocks are an English punk rock band formed in Bolton, Greater Manchester, UK in 1976, led by singer-songwriter and guitarist Pete Shelley (1955 – 2018) for nearly their entire existence.  They are commonly regarded as an important influence on the Manchester music scene, the independent record label movement and the punk rock, power pop, and pop punk genres in general. They are primarily remembered for their singles, a string of would-be hits that combined a strong grasp of pop song craftsmanship with rapid-fire punk energy.', '1098525', '19247483', 'https://www.last.fm/music/Buzzcocks');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('U.K. Subs', 'a57d7a1b-b7ef-4f36-bbf6-9f5a167cd08d', 'GB', 1977, '[]', '["punk", "punk rock", "seen live", "classic pop and rock"]', 'U.K. Subs are an English punk rock band, among the earliest in the first wave of British punk. Formed in 1976, the mainstay of the band has been vocalist Charlie Harper, originally a singer in Britain''s R&B scene. They were one of the first hardcore punk bands.', 'https://en.wikipedia.org/wiki/UK_Subs', '2026-05-23 16:25:54', 11, 'UK Subs', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Screensaver', '6331f1dd-5107-47f9-bbd9-04641856b4de', NULL, NULL, '[]', '[]', 'A screensaver (or screen saver) is software that controls a  monitor of the host computer with the intent of preventing screen burn-in for a screen susceptible to it. Generally, a screensaver starts controlling a monitor when the computer has been idle for a designated period of time and fills the screen either with black (all pixels off) or with changing graphics that tend to prevent each pixel from being on for a long time. Although monitors were commonly constructed with screen technology tha', 'https://en.wikipedia.org/wiki/screensaver', '2026-05-23 16:26:00', 20, 'screensaver', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Fuzz', '1625819f-79d7-4787-b2fb-0e0c260bac85', 'US', 2012, '[]', '["heavy psych", "noise rock", "psychedelic rock"]', 'Fuzz may refer to:', 'https://en.wikipedia.org/wiki/Fuzz', '2026-05-23 23:41:46', 14, 'Fuzz', '["Garage Rock", "Stoner Rock", "Psychedelic Rock", "psychedelic", "rock"]', 'Fuzz is Ty Segall (drums/vocals), Charlie Moothart (guitar/vocals), and Chad Ubovich (bass).  They''re heavy-rock lifers and three California-bred dudes who have been refining their riffs and getting weird together since high school. (which wasn''t that long ago, actually)  Fuzz was formed in/around 2011 as a collaboration between Segall and Moothart, but its only within the last year that the pair had sufficient time to guide the band out of side-project limbo and into a recording studio.', '217376', '3620795', 'https://www.last.fm/music/Fuzz');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Flin Flon', '1ea9168f-d0ae-40cc-a9ed-e82f26078ad8', 'US', NULL, '[]', '[]', 'Flin Flon (pop. 5,185 in 2016 census; 4,982 in Manitoba and 203 in Saskatchewan) is a mining city, located on a correction line on the border of the Canadian provinces of Manitoba and Saskatchewan, with the majority of the city located within Manitoba. Residents thus travel southwest into Saskatchewan, and northeast into Manitoba. The city is incorporated in, and is jointly administered by both provinces.', 'https://en.wikipedia.org/wiki/Flin_Flon', '2026-05-23 23:41:47', 47, 'Flin Flon', '["teenbeat", "indie", "post-punk", "indie pop", "All"]', 'A drums and bass heavy trio with a pop sensibility. Rhythmic. Occasionally danceable. Mark Robinson was in UNREST and AIR MIAMI. Nattles was a member of COLD COLD HEARTS. Matt Datesman (M.D.) still rocks with Charlottesville, VA''s TRUE LOVE ALWAYS. All three members lived in New Jersey when they were younger.', '8089', '123419', 'https://www.last.fm/music/Flin+Flon');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Gyasi', '4f09c3f8-6a69-44f3-ba29-3da786f1ff1f', NULL, NULL, '[]', '["blues", "glam rock", "psychedelia", "rock", "glam", "psychadelia", "rock and roll"]', 'Gyasi is both a surname and given name popular in Ghana. Notable people with this name include:', 'https://en.wikipedia.org/wiki/Gyasi', '2026-05-23 23:41:47', 12, 'Gyasi', '["glam rock", "Psychedelic Rock", "proto-punk", "soft rock", "psychedelic"]', 'There are at least 3 artists with the name Gyasi: 1) A glam rocker from West VA, US. 2) An R&B band (unknown location). 3) A hip-hop/rap artist from the US.  --==-==-- 1) Pronounced Jah-see, Gyasi seems in many ways to come from another planet, and being raised in the woods of a West Virginia holler might as well be another planet in this day and age. His parents bought him a guitar at a local flea market when he was six years old and he still hasn’t gotten rid of the fleas.', '4990', '40384', 'https://www.last.fm/music/Gyasi');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('River City Tanlines', 'b40b34db-4b9d-479d-a2c3-55460f95d97a', 'US', 2004, '[]', '[]', NULL, NULL, '2026-05-23 23:41:48', 20, 'River City Tanlines', '["Garage Punk", "punk", "punk rock", "power pop", "pop punk"]', 'Being the busy gal that she is, it''s remarkable that Alicja Trout is able to crank out so many listenable records with so many different bands -- she plays with the Lost Sounds, Destruction Unit and Mouserocket as well as River City Tanlines, and runs the Contaminated Records label as well as a recording studio. What''s all the more remarkable is that each band actually manages to have its own personality, and on their second album, River City Tanlines conjure up a distinct blend of garage rock, hard rock and pop-punk.', '6178', '55860', 'https://www.last.fm/music/River+City+Tanlines');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Season 2', '1e240897-a943-4ed3-bf91-f794115187de', 'AU', 2024, '[]', '["new wave"]', 'Season 2 may refer to:', 'https://en.wikipedia.org/wiki/Season_2', '2026-05-23 23:51:56', 5, 'Season 2', '[]', NULL, '2624', '9711', 'https://www.last.fm/music/season+2');
