INSERT OR IGNORE INTO "artist_enrichment" VALUES('Lee Perry w/ Mouse On Mars', '4d4f5d92-0589-42fa-bc0e-1bd73e17a2ce', 'DE', 1993, '[]', '["electronic", "ambient", "experimental", "idm", "techno", "glitch", "too pure", "the lost generation"]', NULL, NULL, '2026-05-23 16:26:30', 1, 'Mouse on Mars', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Wand', '5dc7b78d-7777-4dd7-87e2-fbe9f42f7e42', 'US', 2013, '[]', '["neo-psychedelia", "garage rock", "psychedelic rock"]', NULL, NULL, '2026-05-23 23:41:54', 4, 'Wand', '["Psychedelic Rock", "Garage Rock", "psychedelic", "heavy psych", "USA"]', 'When the Los Angeles group Wand formed in 2013, they played a wickedly spooky brand of psychedelic garage rock tinged with heavy metal. Over the course of three albums recorded in a couple years, the band''s leader Cory Hanson wielded full control over their claustrophobic sound. The band''s lineup changed along the way and Hanson loosened his grip on their sonic boundaries, allowing the new bandmembers more say in their newly classic rock- and modern pop-influenced approach. 2017''s Plum was the first Wand album to reflect this change.', '188115', '3239596', 'https://www.last.fm/music/Wand');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Devo', 'd2db1078-c170-4e22-b261-14f3ad60a690', 'US', 1972, '[]', '["rock", "electronic", "synthpop", "punk", "american", "punk rock", "post-punk", "new wave", "synth-pop", "experimental rock", "electropunk", "geek rock", "art punk", "nerd rock", "classic pop and rock", "proto-punk", "electronic rock", "zolo", "synth-punk", "weird america"]', NULL, NULL, '2026-05-23 16:26:32', 159, 'DEVO', NULL, NULL, NULL, NULL, NULL);
