INSERT OR IGNORE INTO "artist_enrichment" VALUES('Unrest', 'f444dc7d-59c1-4ed6-beb7-f90b6d85366c', 'US', 1983, '[]', '["indie rock", "indie pop", "4ad"]', NULL, NULL, '2026-05-23 23:42:22', 44, 'Unrest', '["heavy metal", "indie", "grindcore", "indie rock", "Crust"]', 'there are multiple artists with this name: 1. An American indie rock band 2. A German heavy metal band 3. An American grindcore band 4. An American hardcore band 5. A Bulgarian crust band 6. A Scouse punk band. 7. An American black metal band.  1. An indie band from Washington DC, Unrest formed in 1983 and were initially made up of Mark Robinson (lead guitar) and Phil Krauth (drums). In this form they experimented with a range of genres, and pinning them down was virtually impossible.', '77076', '1114417', 'https://www.last.fm/music/Unrest');
