INSERT OR IGNORE INTO "artist_enrichment" VALUES('Activity', 'ae5080b7-73b8-49f3-982f-2895f22e8dfc', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:42:52', 1, 'Activity', '["experimental", "electronic", "post-rock", "ambient", "3"]', 'Activity is a Brooklyn, NY, United States-based experimental rock band, featuring Travis Johnson (lead vocals, multi-instrumentalist), Jess Rees (guitar, vocals, keys), Bri DiGioia (bass,vocals) and Steven Levine (drums). Their debut album, Unmask Whoever, came out in March 2020. Two more albums followed: Spirit in the Room (2023) and A Thousand Years in Another Way (2025).', '10595', '98494', 'https://www.last.fm/music/Activity');
