INSERT OR IGNORE INTO "artist_enrichment" VALUES('Upchuck', 'e64417df-87c9-4f27-b6f5-ba93a8099310', 'US', NULL, '["punk"]', '["punk"]', 'Upchuck may refer to:', 'https://en.wikipedia.org/wiki/Upchuck', '2026-05-23 23:43:04', 45, 'Upchuck', '["doom punk", "punk rock", "riot grrrl", "Heavy Punk", "Crank wave"]', 'Upchuck is band based out of Atlanta, Georgia formed in 2018. The sound has been developed by pulling from influences in punk, garage rock, psychedelic, doom and hip hop.   https://upchuckatl.bandcamp.com/', '54681', '534757', 'https://www.last.fm/music/Upchuck');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Saints', '0f1e84e4-2417-4f9e-a3f4-6db2cf11a46d', 'AU', 1973, '[]', '["rock", "punk", "punk rock", "classic rock", "pop rock", "rock and indie"]', NULL, NULL, '2026-05-23 23:43:04', 70, 'The Saints', '["punk", "punk rock", "australian", "70s", "rock"]', 'There are multiple bands/acts with this name:  1) The Saints was a punk-rock band formed in 1974 in Brisbane, Australia. Their musical inspiration came from sources as diverse as 1950s rock ''n'' roll and 1960s Detroit punk band The Stooges. The Saints music pioneered the fast tempos and buzzing guitars parallel to more widely-known punk acts like The Ramones and the Sex Pistols.  In mid-1977 the band moved to the UK, where it became apparent that they and their label had different ideas as to how they should be marketed.', '187859', '2439170', 'https://www.last.fm/music/The+Saints');
