INSERT OR IGNORE INTO "artist_enrichment" VALUES('Black Beach', '79f5a25b-8ff5-4d49-b14d-1f7879378d06', NULL, NULL, '[]', '[]', 'Black Beach (Spanish: Playa Negra) is a prison located on the island of Bioko, in the former capital city of Malabo in Equatorial Guinea. It is considered one of Africa''s most notorious prisons.', 'https://en.wikipedia.org/wiki/Black_Beach', '2026-05-23 23:43:33', 2, 'Black Beach', '["Grunge", "rock", "Psychedelic Rock", "Garage Rock"]', 'Stemming from various bands that guitarist/vocalist Steven Instasi and bassist Ben Semeta had been in since their teenage years, Black Beach formed in 2012 in their hometown of Middleboro, MA when the two joined with childhood friend and drummer Ryan Nicholson. Originally starting as a hardcore band, the trio decided to focus on writing a style of music that encompassed all of their interests rather than existing in the confines of any one particular genre.', '4460', '21420', 'https://www.last.fm/music/Black+Beach');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Les Tambours De Brazza', '3325d297-2a7d-4b5c-84ab-57bd792cbc33', 'FR', 1991, '[]', '[]', NULL, NULL, '2026-05-23 16:32:45', 1, 'Les Tambours de Brazza', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Slayer', 'bdacc37b-8633-4bf8-9dd5-4662ee651aec', 'US', 1981, '[]', '["80s", "heavy metal", "90s", "thrash metal", "metal", "american", "nu metal", "speed metal", "crossover thrash", "80s thrash metal", "00s", "rock and indie", "classic metal", "10s", "classic thrash metal", "thrash-metal", "first wave black metal", "2008 universal fire victim", "estados unidos", "vyrzukhisuc-artiest"]', NULL, NULL, '2026-05-23 23:43:34', 8, 'Slayer', '["thrash metal", "metal", "speed metal", "heavy metal", "thrash"]', 'Slayer is an American thrash metal band from Huntington Park, California, formed in 1981 by Kerry King, Jeff Hanneman, Dave Lombardo, and Tom Araya. The band became known for a fast and aggressive style that placed it among the big four of thrash metal alongside Metallica, Megadeth, and Anthrax. The lineup later included Paul Bostaph on drums and Gary Holt on guitar; Holt initially joined as a touring member in 2011 and became a permanent member following Hanneman’s death in 2013. Drummer Jon Dette is a former member.', '2365234', '139117304', 'https://www.last.fm/music/Slayer');
