INSERT OR IGNORE INTO "artist_enrichment" VALUES('Curtis Mayfield', '4dca4bb2-23ba-4103-97e6-5810311db33a', 'US', 1942, '[]', '["psychedelic soul", "singer-songwriter", "smooth soul", "r&b", "death by diabetes", "rnb", "american", "soul", "funk", "soul and reggae", "chicago soul", "crooners"]', NULL, NULL, '2026-05-23 23:44:25', 8, 'Curtis Mayfield', '["soul", "funk", "70s", "rhythm and blues", "rnb"]', 'Curtis Mayfield (June 3, 1942 – December 26, 1999) was an American soul, funk and rhythm and blues, singer-songwriter and guitarist from Chicago, Illinois.  Mayfield is probably best known for his anthemic music with The Impressions and for the soundtrack to the blaxploitation film Superfly.  Perhaps because he didn''t cross over to the pop audience as heavily as Motown''s stars, it may be that the scope of Curtis Mayfield''s talents and contributions have yet to be fully recognized.', '1467248', '20852069', 'https://www.last.fm/music/Curtis+Mayfield');
