INSERT OR IGNORE INTO "artist_enrichment" VALUES('Alan Vega', 'dd720ac8-1c68-4484-abb7-0546413a55e3', 'US', 1938, '[]', '["electronic", "synthpop", "industrial", "experimental", "post-punk", "new wave", "rockabilly", "minimal", "synth-pop", "experimental rock", "no wave", "power noise", "proto-punk", "minimal synth", "synth punk", "synth-punk"]', NULL, NULL, '2026-05-23 23:23:29', 89, 'Alan Vega', '["experimental", "electronic", "new wave", "rockabilly", "electrobilly"]', 'Alan Vega (Boruch Alan Bermowitz, June 23, 1938 – July 16, 2016) was an American vocalist and visual artist, primarily known for his work with the electronic protopunk duo Suicide.  Alan Bermowitz was raised in a Jewish household in Bensonhurst, Brooklyn. Until the announcement of the 70th birthday release of his recordings in 2008, Vega was widely thought to have been ten years younger; the 2005 book Suicide: No Compromise lists 1948 as his birth', '91174', '843799', 'https://www.last.fm/music/Alan+Vega');
