INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jonny Telafone', '45cb30f7-34bd-48c3-a55e-0e7b11c8f4f4', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:45:00', 7, 'Jonny Telafone', '["witch house", "electronic", "hiphop", "noise", "pop"]', 'Steeped in the heartache and boredom that can come with being heartbroken and bored Jonny Telafone''s music does not fall easily into any sub-genre or scene. It''s all pop music...Hit after hit', '5609', '49592', 'https://www.last.fm/music/Jonny+Telafone');
