INSERT OR IGNORE INTO "artist_enrichment" VALUES('Skull Practitioners', 'a58ba2d2-4c9d-4a28-b461-113343dbee88', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:45:18', 7, 'Skull Practitioners', '["punk", "Garage Rock", "post-punk"]', 'Three piece featuring Jason Victor (current lead guitarist in the Dream Syndicate), Kenneth Levine and Alex Baker. This band’s brand of heavy psych post punk skronk is some of the fresh coolest sounds around. Jason’s guitar shredding is positively brain splattering and Kenneth’s huge bass throb and Alex’s propulsive drumming make these guys sound bigger and heavier than most five piece bands.', '1108', '7574', 'https://www.last.fm/music/Skull+Practitioners');
