INSERT OR IGNORE INTO "artist_enrichment" VALUES('Gee Tee', '2ce1b4bf-4bff-4954-b741-2ca70cb35c7f', 'AU', NULL, '["garage punk", "garage rock"]', '["garage punk", "garage rock"]', NULL, NULL, '2026-05-23 23:45:28', 38, 'Gee Tee', '["egg punk", "Garage Punk", "synthpunk", "Garage Rock", "punk"]', 'Sick band. Gee Tee is a garage / synth punk band from Sydney Australia. Formed by Frontman Kel Mason in 2016-2017 after Australian punk band Draggs split in 2017. Gee Tee have so far released two full length LPs, two live albums and six EP/Singles. Goodnight Neanderthal was released March 3, 2023.', '106942', '1961423', 'https://www.last.fm/music/Gee+Tee');
