INSERT OR IGNORE INTO "artist_enrichment" VALUES('David Lynch', '752d58e6-d33f-4dcd-b40c-37acc14242f2', 'US', 1946, '[]', '["experimental", "electronica", "avant-garde"]', NULL, NULL, '2026-05-23 23:46:04', 15, 'David Lynch', '["experimental", "dark ambient", "Avant-Garde", "ambient", "Soundtrack"]', 'David Keith Lynch (January 20, 1946 – January 16, 2025) was an American filmmaker, visual artist, musician, and actor. He received critical acclaim for his films, which are often distinguished by their surrealist, dreamlike qualities. In a career spanning more than fifty years, he was awarded with numerous accolades, including the Golden Lion for Lifetime Achievement at the Venice Film Festival in 2006 and an Honorary Academy Award in 2019. Described as a "visionary", Lynch was considered one of the most important filmmakers of his era.', '332823', '5199072', 'https://www.last.fm/music/David+Lynch');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Iggy & The Stooges', '1253e5e9-eaa7-4ce6-81b8-09725e8cee43', 'US', 1972, '[]', '["proto-punk", "garage rock", "punk", "classic rock", "rock", "punk rock", "hard rock"]', NULL, NULL, '2026-05-23 16:40:36', 7, 'Iggy and The Stooges', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Wesley Willis', 'b0a16d0c-3d99-487d-be88-902131ad03d3', 'US', 1963, '[]', '["punk rock", "outsider", "synth-punk"]', NULL, NULL, '2026-05-23 23:46:07', 2, 'Wesley Willis', '["outsider", "rock", "comedy", "Lo-Fi", "alternative"]', 'Wesley Willis (May 31, 1963 – August 21, 2003) was an African-American musician from Chicago, Illinois, who became a well-known underground figure in the 1990s. Standing at 6-foot-6 inches and weighing 350 lbs., Willis was diagnosed with schizophrenia as a young adult. He released several hundred songs of bizarre and simplistic music, which spread through the early days of P2P file sharing.  Willis had a tumultuous childhood, growing up in various foster homes.', '149958', '1470141', 'https://www.last.fm/music/Wesley+Willis');
