INSERT OR IGNORE INTO "artist_enrichment" VALUES('Embrace', '77f049ad-f469-4ad1-8283-7a2606a6722e', 'GB', 1993, '[]', '["alternative rock", "british", "uk", "indie rock", "britpop", "post-grunge", "indie pop", "pop rock", "piano rock", "english", "rock and indie", "post-britpop"]', NULL, NULL, '2026-05-23 23:46:52', 12, 'Embrace', '["emo", "post-hardcore", "britpop", "indie", "hardcore"]', 'Embrace is the name of more than one artist: 1) an alternative rock band from Brighouse, West Yorkshire, England 2) a short-lived post-hardcore band from Washington, D.C., USA 3) a collaboration between dutch trance producers Ferry Corsten and Raz Nitzan 4) a Gothic Metal band from Toronto, Canada  1) Embrace is a five-piece alternative rock band from Brighouse, West Yorkshire, England, consisting of brothers Danny McNamara (singer) and Richard McNamara (guitarist) as well as Steve Firth (bassist)', '676637', '9062077', 'https://www.last.fm/music/Embrace');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Tel Aviv', 'd08753f5-cb30-4e65-8e14-a76556a15c03', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:46:53', 18, 'Tel Aviv', '[]', 'Originally from Little Rock, AR & Hot Springs. They play it up in Fayetteville and throw fabulous vinyl parties. Lots of synth/keyboards/drums and maracas.', '2508', '18836', 'https://www.last.fm/music/Tel+Aviv');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Le Shok', '96089d91-5b36-4a6b-9ed3-c7b382989be2', 'US', 1997, '[]', '[]', NULL, NULL, '2026-05-23 23:46:53', 1, 'Le Shok', '["Lo-Fi", "punk", "synthpunk", "noise rock", "Garage Punk"]', 'Le Shok was a new wave punk rock band from Long Beach, California.  Formed in 1997, the band began as The Shock and originally consisted of Treadwell bassist Asshole Andrew, The Locust keyboardist Joey Juvenile, and singer Hot Rod Todd.  The three members eventually attempted to convince Crimson Curse vocalist/The Locust bassist Justin Pearson to join the band. Pearson ultimately did not join Le Shok. After hearing a crude demo tape, Action League bassist Darryl Licht joined the band as the keyboardist.', '10885', '266803', 'https://www.last.fm/music/Le+Shok');
