INSERT OR IGNORE INTO "artist_enrichment" VALUES('Paloma 004', 'c22cd31c-deb8-414a-9875-817bb7cf3878', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:53:23', 3, 'Paloma 004', '[]', NULL, '80', '1253', 'https://www.last.fm/music/Paloma+004');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Dee Dee King', '7859e480-dc40-4186-885d-dc403ddeb5b2', 'US', 1951, '[]', '[]', NULL, NULL, '2026-05-23 23:46:54', 13, 'Dee Dee King', '["Hip-Hop", "punk", "old school rap", "rap", "punk rock"]', 'Dee Dee King is Dee Dee Ramone''s second pseudonym (real name Douglas Colvin) for his one-off 1989 hip-hop album, titled ''Standing in the Spotlight''. Debbie Harry notably performed guest vocals on some of his tracks. Dee Dee once said he got the idea from a time when he was in a hospital and the kids there called him Doug E. Fresh. His album is often regarded as one of the worst recordings of all time by critics such as those at the All Music Guide, although a cult following exists among devotees of outsider music.', '7146', '83027', 'https://www.last.fm/music/Dee+Dee+King');
