INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Beatles', 'b10bbbfc-cf9e-42e0-be17-e2c3e1d2600d', 'GB', 1960, '[]', '["rock", "pop", "progressive rock", "80s", "heavy metal", "pop-rock", "orchestral", "experimental", "british", "uk", "60s", "hard rock", "indie rock", "folk rock", "psychedelic rock", "psychedelic", "blues rock", "britpop", "art rock", "folk-rock", "baroque pop", "classic rock", "1960s", "psychedelic pop", "experimental rock", "pop rock", "europop", "british invasion", "rock and roll", "rock roll", "beat", "english", "sunshine pop", "folk pop", "rock music", "liverpool", "parlophone", "united kingdom", "hair metal", "europe", "1", "bbc", "film soundtrack", "classic pop and rock", "singer songwriter", "classical pop", "instrumental pop", "merseybeat", "adult alternative pop rock", "tribute albums", "british psychedelia", "orchestral pop", "pop-metal", "psychedelia", "male vocalists", "the-beatles", "mainstream rock", "boys band", "abbey road", "rock & roll", "pop/rock", "rhythm & blues", "overrated", "psychedelic/garage", "art pop", "one beatles", "popular music", "a filk artist", "british rhythm & blues", "beat music", "get back", "favoritos", "the beatles - primal colours", "reino unido", "rock groups", "vyrzukhisuc-artiest"]', NULL, NULL, '2026-05-23 23:47:22', 5, 'The Beatles', '["classic rock", "rock", "british", "60s", "pop"]', 'The Beatles were an English rock band formed in Liverpool in 1960. The group’s core lineup consisted of John Lennon, Paul McCartney, George Harrison and Ringo Starr. They are widely regarded as one of the most influential acts in popular music and played a central role in the development of 1960s counterculture. The Beatles’ music incorporated elements of skiffle, beat, 1950s rock and roll, classical music and traditional pop, and they explored styles including folk, Indian music, psychedelia and hard rock.', '6546340', '1110570851', 'https://www.last.fm/music/The+Beatles');
