INSERT OR IGNORE INTO "artist_enrichment" VALUES('Kilynn Lunsford', 'edb5b865-c245-4b3e-9fa2-c73d17bc9adb', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:47:30', 22, 'Kilynn Lunsford', '["experimental", "rock", "singer-songwriter", "guitar", "vocal"]', 'Kilynn Lunsford is a New Jersey-based musician, visual artist, and labor organizer. With over two decades of experience in experimental noise punk, she has been involved in numerous projects and has released music through labels such as Kill Rock Stars, Ecstatic Peace, Not Not Fun, Siltbreeze, and ever/never.', '2997', '15828', 'https://www.last.fm/music/Kilynn+Lunsford');
