INSERT OR IGNORE INTO "artist_enrichment" VALUES('Bananach', '675ca3dc-2ee1-4dae-8d60-361b03e1423a', 'ID', 2018, '[]', '[]', NULL, NULL, '2026-05-23 23:47:38', 5, 'Bananach', '["female vocal", "punk", "garage", "punk rock", "indonesia"]', 'Bananach is an energetic heavy dizzy tunes band from Bandung, Indonesia that formed in 2014. Since mid-2017 Bananach is back on track with a concept that mixes rock with punk. They released Panoptic Litter in 2022 and have since signed to Damnably records, of London, England.  https://bananachtunes.bandcamp.com/', '751', '5432', 'https://www.last.fm/music/Bananach');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Olivia Neutron-John', '0dcdf94b-353f-40db-b715-4ca84b0eee30', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:47:39', 19, 'Anna Nasty', '["experimental", "electronic", "bands that would eat children if only they could fit a whole one inside their mouths", "post-punk", "bedroom pop"]', 'Olivia Neutron-John, a.k.a. Anna Nasty, keeps things simple and somewhat scary onstage, whispering and groaning over the sounds generated by a vintage Casio keyboard.  http://olivianeutron-john.bandcamp.com/', '2080', '9697', 'https://www.last.fm/music/Olivia+Neutron-John');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Rocket From The Tombs', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:47:39', 2, 'Rocket From The Tombs', '["proto-punk", "Garage Rock", "punk", "garage", "rock"]', 'Formed in the early 70''s by the monstrous Crocus Behemoth (aka David Thomas), Rocket from the Tombs represented Cleveland''s dying factories and urban wasteland just as the Detroit pre-punks had done in regards to their decaying city. After sometime, the group caught the eye of guitarist Peter Laughner. Laughner joined RFTT and along with bassist Craig Bell, drummer John Madansky, and guitarist Gene O''Connor, the lineup was solidified.   From the beginning', '52099', '493937', 'https://www.last.fm/music/Rocket+From+The+Tombs');
