INSERT OR IGNORE INTO "artist_enrichment" VALUES('Empire', '71eb7eb0-1154-4a6d-a3df-51ddcd05364f', 'JP', 2017, '[]', '["idol", "japanese", "wack"]', NULL, NULL, '2026-05-23 23:47:40', 25, 'EMPiRE', '["hard rock", "heavy metal", "metalcore", "JPop", "Progressive rock"]', 'There are (or were) at least 14 bands called Empire including a podcast produced by the UK film magazine Empire.  1) EMPiRE, were a Japanese female idol group under WACK which debuted in August of 2017 and disbanded 2nd June 2022. They were launched as a joint project between the record label avex and Watanabe Junnosuke. They went by the name "Project aW" before debut. The founding members were YUKA EMPiRE, MiDORiKO EMPiRE, MAYU EMPiRE, YU-Ki EMPiRE, and YUiNA EMPiRE.', '74270', '1176688', 'https://www.last.fm/music/Empire');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Melenas', 'f3291ecb-af2b-457e-8f17-1913aca82cbc', 'ES', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:47:40', 41, 'Melenas', '["post-punk", "Garage Rock", "spain", "indie rock", "spanish"]', 'Melenas are an indie guitar pop band from Pamplona, Spain. Their self-titled début album, Melenas, was released in November 2017. Sophomore outing, Dias Raros, followed in May 2020 on Trouble In Mind Records.', '32432', '375243', 'https://www.last.fm/music/Melenas');
