INSERT OR IGNORE INTO "artist_enrichment" VALUES('Model Zero', 'f35618e3-cab6-4e7b-9aa2-0d955a2829e3', 'US', 2017, '[]', '[]', NULL, NULL, '2026-05-23 23:47:43', 3, 'Model Zero', '["rock", "punk", "alternative rock", "alternative", "post-punk"]', 'Model Zero is an alternative rock / (post)-punk band from Memphis, TN, United States. Members of the SHEIKS (one of Jack Oblivian’s backing bands) and EX-CULT backed by one of MR. QUINTRON’s drum buddies from this Memphis supergroup. With a pedigree this cool, it would be hard to go wrong. MODEL ZERO does not disappoint. Theirs is a retro futuristic style with whirly synths and repetitive beats. The vocals are soulfully plaintive. Plus it’s got a wacky edge.', '370', '3109', 'https://www.last.fm/music/MODEL+ZERO');
