INSERT OR IGNORE INTO "artist_enrichment" VALUES('King Tubby And Friends', '576134a6-9f1f-4bfa-af04-4848195849ca', 'JM', 1941, '[]', '["reggae", "dub", "producer", "roots reggae", "deejay", "soul and reggae", "born in fire", "digital dancehall"]', 'Osbourne Ruddock (28 January 1941 – 6 February 1989), better known as King Tubby, was a Jamaican sound engineer who influenced the development of dub music in the 1960s and 1970s.', 'https://en.wikipedia.org/wiki/King_Tubby', '2026-05-23 16:45:00', 4, 'King Tubby', NULL, NULL, NULL, NULL, NULL);
