INSERT OR IGNORE INTO "artist_enrichment" VALUES('Endless Bummer', 'c5d51123-36a2-4b65-915e-f3cfe20d7d20', NULL, NULL, '[]', '[]', 'Endless Bummer may refer to:', 'https://en.wikipedia.org/wiki/Endless_Bummer', '2026-05-23 23:48:00', 1, 'Endless Bummer', '["punk", "Garage Rock", "Garage Punk", "garage", "Minnesota"]', 'This band name refers to more than one artist:  Minneapolis Doom Metal - http://spitandcuss.blogspot.com/   Hardcore Crusty Punk Band from Baltimore, MD - http://endlessbummer.bandcamp.com/  Releases: -Bummed Out (released October 21, 2012)  Members: Stephen: guitar/vocals Steven: bass/vocals Ben: drums/vocals?', '1961', '23575', 'https://www.last.fm/music/Endless+Bummer');
