INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Robins', 'ef0529c3-db9e-40d3-8c24-954a780baa4c', 'US', 1945, '[]', '["doo-wop", "rhythm & blues"]', NULL, NULL, '2026-05-23 23:48:01', 1, 'The Robins', '["doo wop", "Rock and Roll", "rhythm and blues", "oldies", "pop"]', 'The Robins were formed in 1949 in Los Angeles, California. They had previously been known since 1947 as “The Bluebirds.” The best known recording from the Robins was “Smokey Joe’s Café.” If It’s So Baby was another top 10 R&B hit from the group.  The original group members were Ty Terrell, Billy Richards, Roy Richards, and Bobby Nunn. Carl Gardner and Grady Chapman were added in 1954. In 1956, Garner and Nunn left and formed The Coasters.', '117171', '411462', 'https://www.last.fm/music/The+Robins');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Suburban Lawns', 'f2e5a6f8-e72e-46a7-8e2e-34960339220a', 'US', 1979, '[]', '["long beach", "california", "usa", "post-punk", "new wave", "dance-punk"]', NULL, NULL, '2026-05-23 23:48:02', 1, 'Suburban Lawns', '["new wave", "post-punk", "80s", "Post punk", "obscure 80s"]', 'Suburban Lawns was an American post-punk band formed in Long Beach, California in 1978 by CalArts students William "Vex Billingsgate" Ranson and Sue "Su Tissue" McLane. They later recruited Richard "Frankie Ennui" Whitney, Charles "Chuck Roast" Rodriguez, and John "John Gleur" McBurney.  After forming in 1978, Suburban Lawns released their debut single, "Gidget Goes to Hell", in 1979 on their own Suburban Industrial label. The song gained the band notoriety when its Jonathan Demme-directed music video was shown on Saturday Night Live.[1]', '115732', '1578114', 'https://www.last.fm/music/Suburban+Lawns');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jay Reatard & Lindsay Shutt', '6338a3a4-1676-4a99-b2fb-a3f0072f6b42', 'US', 1980, '[]', '["punk rock", "indie rock", "garage punk", "garage rock"]', NULL, NULL, '2026-05-23 16:46:38', 1, 'Jay Reatard', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Hand Hell', 'c3fd3ecd-cdee-4952-be34-ad33f8be1b4f', NULL, 2006, '[]', '[]', NULL, NULL, '2026-05-23 23:48:02', 2, 'Hand Hell', '["under 2000 listeners", "australia"]', 'Hand Hell are Kirsty Stegwazi (guitar/vocals), René Schaefer (guitar and bass) and Ricky French (Drums), an independent rock trio from Melbourne, Australia.  Hand Hell released their debut album Phonography in 2007.  After four years of playing under the moniker The Bites, with a variety of different line-ups, Melbourne songwriters Kirsty Stegwazi and René Schaefer decided it was time to make a fresh start to allow for an expanded musical palette and a fresh approach to writing and recording.', '81', '3241', 'https://www.last.fm/music/Hand+Hell');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Fitness Womxn', 'f9a81c4d-501f-44fb-8a1a-b4bdd03fe330', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:48:03', 11, 'Fitness Womxn', '["punk", "female vocal", "Post punk", "post-punk", "North Carolina"]', 'American post-punk band from Carrboro, North Carolina.', '531', '3683', 'https://www.last.fm/music/Fitness+Womxn');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Flat Worms', '5f647289-9ff8-494d-a349-7a388307ddde', 'US', NULL, '[]', '["elmiene"]', NULL, NULL, '2026-05-23 23:48:03', 15, 'Flat Worms', '["post-punk", "Heavy Punk", "doom punk", "Garage Rock", "Psychedelic Rock"]', 'Something of a supergroup in the West Coast garage punk community, Flat Worms are a clever, cheerfully abrasive trio who confirm you don''t have to be an angry teenager to play great punk rock. Dealing in choppy guitar figures bathed in feedback and distortion, paired with strong, throbbing rhythms, Flat Worms have mastered the art of sounding serious on the surface while clearly enjoying their lo-fi chaos, and their 2017 self-titled album and the 2019 EP Into the Iris are commendable unions of punky troublemaking and indie rock smarts.', '45909', '432462', 'https://www.last.fm/music/Flat+Worms');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Shag', '3fc5db61-ad1a-42d4-b468-cb30638aa9d6', 'US', NULL, '[]', '["psychedelic rock", "garage rock"]', NULL, NULL, '2026-05-23 23:48:04', 1, 'The Shag', '["60s garage", "Garage Punk", "psychedelic", "american", "Greg Cartwright"]', 'Garage psych rock band originally from Milwaukee WI, active from 1964-1971.  (For the Canadian rock band, see Shag.)  They were called The Shags and featured a more folksy/blues rock sound however, after some personal changes the band proceeded onto new directions.  In 1965, they recorded a single, "Dance Woman" on their local Raynard label before original guitarist John Sahli left and was replaced with Ray McCall. In 1967, they were signed by Capitol Records and recorded a 45', '2243', '8117', 'https://www.last.fm/music/The+Shag');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Escape-Ism', '9100963e-18e6-4c0e-8475-a17e4fc15303', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-23 16:46:45', 37, 'ESCAPE‐ISM', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Non!', 'e16bbdb0-b7aa-4449-a206-421f52b9deb5', 'US', 1956, '[]', '[]', NULL, NULL, '2026-05-23 16:46:49', 4, 'NON', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Delivery', '8ea1a45f-4a8a-494b-bda1-b44ab2ba376a', 'GB', 1968, '[]', '["uk", "british", "english"]', NULL, NULL, '2026-05-23 23:48:05', 23, 'Delivery', '["Progressive rock", "Canterbury Scene", "Jazz Rock", "Garage Punk", "techno"]', 'There are multiple artists using the name Delivery.  1. Post-punk band from Melbourne, Australia. Formed in lockdown by Rebecca Allan (Gutter Girls, Blonde Revolver) and James Lynch (The Vacant Smiles, Kosmetika), and now rounded out by Lisa Rashleigh (Soursob), Daniel Devlin (Heir Traffic, House Deposit) and Seamus Whelan (The Vacant Smiles). On their debut  EP "Yes We Do", Delivery unveil a restless and neurotic blitz over four tracks that fuses urgent garage-rock together with nervy post-punk and weirdo new-wave smarts.', '20228', '157079', 'https://www.last.fm/music/Delivery');
