INSERT OR IGNORE INTO "artist_enrichment" VALUES('Eggy', 'ba0b9dc6-bd61-42c7-a28f-5179b1c04391', 'US', 2016, '[]', '["psychedelic", "dance", "indie rock", "jam band", "psychedelic rock", "funk"]', NULL, NULL, '2026-05-23 23:48:06', 25, 'Eggy', '["jam band", "Psychedelic Rock", "Jam", "rock", "australia"]', '[1] Eggy is from New Haven, Connecticut. They are a four-piece jam band known for their eclectic style and high-energy live performances, blending funk, psychedelic rock, blues, and more.   [2) This name can also refer to an experimental rock band from Melbourne, Australia.', '14789', '139231', 'https://www.last.fm/music/Eggy');
