INSERT OR IGNORE INTO "artist_enrichment" VALUES('Hildegard Knef', 'fef1e787-e631-41a3-b8f2-a834291d8bd1', 'DE', 1925, '[]', '["german", "actress"]', 'Hildegard Frieda Albertine Knef (German: [ˈhɪldəɡaʁt ˈkneːf] ; 28 December 1925 – 1 February 2002) was a German actress, singer, and writer. She was billed in some English-language films as Hildegard Neff or Hildegarde Neff.', 'https://en.wikipedia.org/wiki/Hildegard_Knef', '2026-05-23 23:49:00', 1, 'Hildegard Knef', '["chanson", "german", "female vocalists", "deutsch", "oldies"]', 'Hildegard Frieda Albertine Knef (* 28 December 1925 in Ulm; † 1 February 2002 in Berlin) was a German actress, voice actress, chanson singer, and author. While she was known as Hildegard Knef in German-speaking countries, she referred to herself as Hildegarde Neff outside of the German-speaking world from 1948 to around 1968. She became a US citizen in 1950 and regained German citizenship in 2001.  Knef began her film career at the end of the Nazi', '89507', '1175398', 'https://www.last.fm/music/Hildegard+Knef');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Holger Czukay, Jah Wobble, Jaki Liebezeit', 'e779daf9-9481-41c6-a3e9-f1b48aabd829', 'DE', 1938, '[]', '["krautrock", "post-punk", "dub", "ambient dub", "electronic", "progressive electronic", "jazz"]', 'Jaki Liebezeit (born Hans Liebezeit; 26 May 1938 – 22 January 2017) was a German drummer, best known as a founding member of experimental rock band Can. He was called "one of the few drummers to convincingly meld the funky and the cerebral".', 'https://en.wikipedia.org/wiki/Jaki_Liebezeit', '2026-05-23 16:52:04', 1, 'Jaki Liebezeit', NULL, NULL, NULL, NULL, NULL);
