INSERT OR IGNORE INTO "artist_enrichment" VALUES('Kip Tyler', 'b1399a5c-29ed-403c-9dea-fe0f8b2e9fe3', 'US', 1929, '[]', '["rockabilly", "psychobilly"]', NULL, NULL, '2026-05-23 23:49:14', 6, 'Kip Tyler', '["rockabilly", "Rock and Roll", "rock n roll", "rock", "Need to Rate"]', 'Kip Tyler (real name: Elwood Westertson Smith; born May 31, 1929 Chicago, Illinois; died September 23, 1996, Los Angeles, California) was American rock and roll singer and bongo player. His backing band was called The Flips, their line up was Jim Horn, Larry Knechtel, Mike Bermani, Mike Deasy , Sandy Nelson and Steve Kreisman.  Kip Tyler was lead singer of Sleepwalkers during his time at Union High School and later teamed up with rival musicians from Fairfax High School to form the early version of Kip Tyler and the Flips.', '95526', '420582', 'https://www.last.fm/music/Kip+Tyler');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Georgie James', 'c4cfd21d-fd5e-45ae-88f2-413f9e15d944', 'US', 2005, '[]', '[]', NULL, NULL, '2026-05-23 23:49:15', 7, 'Georgie James', '["indie pop", "indie", "female vocalists", "indie rock", "Home collection"]', 'Georgie James was a classic four-piece pop/rock outfit from Washington DC, US formed in 2005, featuring John Davis (ex-drummer of the defunct Q and Not U) and D.C.-based singer-songwriter Laura Burhenn.  Having met through mutual friends, Davis and Burhenn (who had released 4 solo albums on her own Laboratory Records prior this project) found out that they both had an affinity for retro-pop from the 1950-70''s; subsequently, they decided to start working together as a band derived from said style.', '35013', '366834', 'https://www.last.fm/music/Georgie+James');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Felt Letters', 'e6804e84-ebfd-4aa1-8b9a-4bf3c92004e2', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:49:16', 4, 'Felt Letters', '["punk", "spoken word", "Lo-Fi", "post-punk", "Brendan Canty of Fugazi on drums"]', 'The Felt Letters is a new project by Ian Svenonius (Nation of Ulysses, Make Up, Weird War, Chain and the Gang, Brendan Canty (Fugazi, Girls Against Boys), and Tom Bunnell.  The band formed in Washington, DC.', '287', '1318', 'https://www.last.fm/music/Felt+Letters');
