INSERT OR IGNORE INTO "artist_enrichment" VALUES('Trupa Trupa', '31687f99-ddfd-4d23-8609-08020b7b386f', 'PL', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:49:35', 20, 'Trupa Trupa', '["indie rock", "Garage Rock", "noise rock", "Psychedelic Rock", "post-punk"]', 'Trupa Trupa is a Polish band, based in Gdansk. Its current members are Grzegorz Kwiatkowski, Wojtek Juchniewicz, Tomek Pawluczuk and Rafał Wojczal.', '21074', '262322', 'https://www.last.fm/music/Trupa+Trupa');
