INSERT OR IGNORE INTO "artist_enrichment" VALUES('Nancy Sinatra', 'c2e36518-9c3b-4dcb-82ad-a3fc7fe99c67', 'US', 1940, '[]', '["rock", "pop", "classic rock", "pop rock", "classic pop and rock"]', NULL, NULL, '2026-05-23 23:49:36', 6, 'Nancy Sinatra', '["60s", "female vocalists", "pop", "oldies", "classic rock"]', 'Nancy Sandra Sinatra Jr (born June 8, 1940, in Jersey City, New Jersey, United States) is a singer and actress. She is the daughter of the legendary singer Frank Sinatra and his first wife Nancy Barbato.  Her career peaked in the late 1960s with a string of pop music hits. Her best-known hit, These Boots Are Made for Walkin'' - which popularized and made her synonymous with Go-Go boots - was written by Lee Hazlewood. These Boots... has been covered by many artists such as Geri Halliwell', '1916586', '23260740', 'https://www.last.fm/music/Nancy+Sinatra');
