INSERT OR IGNORE INTO "artist_enrichment" VALUES('Mississippi Fred McDowell', '8d2651e1-f539-4492-957a-8b4dc4c5d9b9', 'US', 1904, '[]', '["blues", "delta blues", "hill country blues"]', 'Fred McDowell (January 12, 1904 – July 3, 1972), known by his stage name Mississippi Fred McDowell, was an American singer-songwriter and guitarist of hill country blues music.', 'https://en.wikipedia.org/wiki/Mississippi_Fred_McDowell', '2026-05-23 23:49:37', 2, 'Mississippi Fred McDowell', '["blues", "delta blues", "Classic Blues", "folk", "acoustic"]', 'Mississippi Fred McDowell was born Fred McDowell in Rossville, Tennessee, January 12, 1904. He died in Memphis,Tennessee on July 3, 1972.  He was a blues singer and guitar player in the North Mississippi style.  His parents, who were farmers, died when McDowell was a youth. He started playing guitar at the age of 14 and played at dances around Rossville. Wanting a change from ploughing fields, he moved to Memphis in 1926 where he worked in a number of jobs and played music for tips.', '190159', '1478176', 'https://www.last.fm/music/Mississippi+Fred+McDowell');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Adaptors', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:49:38', 1, 'Adaptors', '["post-punk", "dub", "House", "techno", "Acid"]', 'ADAPTORS (not to be confused with the Adaptors) are a duo from Amersfoort, the Netherlands. Their music is best described as mostly attic-wise not taking notice of any genre, although there are some obvious ingredients to it... But who cares?', '535', '2673', 'https://www.last.fm/music/Adaptors');
