INSERT OR IGNORE INTO "artist_enrichment" VALUES('Floating Room', '5b0daedb-28b7-449b-bc17-c5da96239884', 'US', NULL, '["dream pop", "electronic", "experimental", "indie rock", "lo-fi", "shoegaze", "slowcore"]', '["dream pop", "electronic", "experimental", "gray pop", "indie rock", "lo-fi", "oregon", "portland", "sadcore", "shoegaze", "slowcore"]', NULL, NULL, '2026-05-23 23:49:47', 9, 'Floating Room', '["shoegaze", "dream pop", "Post punk", "indie"]', 'Floating Room is the musical project of Portland based multidisciplinary Uchinanchu American artist and DIY veteran Maya Stoner (Sabonis). The project formerly included Kyle Bates (Drowse) and bassist Alec Van Staveren.', '12922', '105622', 'https://www.last.fm/music/Floating+Room');
