INSERT OR IGNORE INTO "artist_enrichment" VALUES('Rowland S. Howard', 'ae5077a5-bbcc-4195-b2a4-bd7cd4712f5a', 'AU', 1959, '[]', '["singer-songwriter", "post-punk", "gothic rock", "punk blues"]', NULL, NULL, '2026-05-23 23:49:50', 10, 'Rowland S. Howard', '["post-punk", "singer-songwriter", "blues", "australian", "rock"]', 'Rowland Stuart Howard (24 October 1959 – 30 December 2009) was an influential rock musician, guitarist and songwriter, based in Melbourne, Australia, best known for: his work in the Antipodean discophile art-rock groups Young Charlatans, The Boys Next Door and The Birthday Party (both featuring the singer Nick Cave), Crime and the City Solution and These Immortal Souls; his macabre lyrics and imposing roots-based guitar playing; and his song Shivers, which he wrote early in his career, and for which he received peer group kudos.', '112773', '2305911', 'https://www.last.fm/music/Rowland+S.+Howard');
