INSERT OR IGNORE INTO "artist_enrichment" VALUES('Tunnel', '550d19fe-4007-4468-8bdd-8f37c96cfb72', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:49:51', 7, 'Tunnel', '["Rhythmic Noise", "noise", "industrial", "techno", "alternative rock"]', 'There have been several bands with this name:  1) Italian prog-disco act formed by Danilo Rustici (Osanna, Luna, Città Frontale, etc.).  Released on single - Speed Up/Tunnel Lights in 1978 2) Alias of Austrian drummer, Norbert Wallner. 3) Industrial act formed by Patrick Stevens and Mieke Maes 4) Techno artist Ryan Miller 5) US Hard rock band   Other Tunnels may exist if you dig hard enough.', '3603', '19696', 'https://www.last.fm/music/Tunnel');
