INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ornette Coleman', '169c0d1b-fcb8-4a43-9097-829aa7b39205', 'US', 1930, '[]', '["jazz", "american", "avant-garde jazz", "free jazz", "free funk", "classic pop and rock", "2008 universal fire victim"]', NULL, NULL, '2026-05-23 23:49:52', 19, 'Ornette Coleman', '["jazz", "free jazz", "Avant-Garde", "saxophone", "experimental"]', 'Ornette Coleman (March 9, 1930 - June 11, 2015) was an American jazz saxophonist, violinist, trumpeter, and composer. He was one of the founders and major innovators of the 1960s free jazz movement and one of the most notable figures in jazz history.  Coleman was born in 1930 in Fort Worth, Texas where he participated in his high school band until being dismissed for improvising during "The Washington Post" march. He began performing rhythm and blues and bebop, initially on tenor saxophone.', '374744', '4921711', 'https://www.last.fm/music/Ornette+Coleman');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Roxy Music', '331ce348-1b08-40b9-8ed7-0763b92bd003', 'GB', 1971, '[]', '["glam rock", "new wave", "progressive rock", "new wave pop", "pop rock", "sophisti-pop", "new romantic", "art pop", "soft rock", "synth-pop", "melancholia", "art rock", "uk", "english", "british", "rock and indie"]', NULL, NULL, '2026-05-23 23:49:53', 5, 'Roxy Music', '["glam rock", "new wave", "rock", "classic rock", "80s"]', 'Roxy Music are an English rock band formed in 1970 by Bryan Ferry—who became the band''s lead vocalist and principal songwriter—and bassist Graham Simpson. The other longtime members are Phil Manzanera (guitar), Andy Mackay (saxophone and oboe), and Paul Thompson (drums and percussion). Other members included Brian Eno (synthesizer and "treatments") and Eddie Jobson (synthesizer and violin). Although the band took a break from group activities in 1976 and again in 1983', '1294022', '26850988', 'https://www.last.fm/music/Roxy+Music');
