INSERT OR IGNORE INTO "artist_enrichment" VALUES('Billy Eckstine', 'dc335fdb-9bc6-42ca-86a1-e652318764cc', 'US', 1914, '[]', '["jazz", "swing", "bebop", "vocal jazz", "traditional pop"]', NULL, NULL, '2026-05-23 23:49:55', 3, 'Billy Eckstine', '["jazz", "swing", "blues", "jazz vocal", "male vocalists"]', 'Billy Eckstine (8 July 1914 – 8 March 1993), born in Pittsburgh, Pennsylvania, USA as William Clarence Eckstein. He changed the spelling to Eckstine after a club owner said the original spelling was "too Jewish".  Eckstine was an American jazz singer and bandleader who also played trumpet, valve trombone, and guitar. He also performed briefly as Billy X. Stine. His nickname was Mr. B. Although best known as a singer, his openness to new music made him a strong influence on modern jazz', '229287', '974711', 'https://www.last.fm/music/Billy+Eckstine');
