INSERT OR IGNORE INTO "artist_enrichment" VALUES('Les Vampyrettes', '3e82014b-faaf-46da-be4d-7b8f72fcc7d8', 'DE', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:50:09', 2, 'Les Vampyrettes', '["darkwave", "krautrock", "experimental", "electronic", "NDW"]', 'Les Vampyrettes was an early-''80s collaboration between Can''s Holger Czukay and renowned krautrock producer Konrad Plank.', '2099', '8912', 'https://www.last.fm/music/Les+Vampyrettes');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jackie Lomax', 'bff73e1f-6eac-41fa-b4d6-1287bec82d1f', 'GB', 1944, '[]', '["rock"]', 'John Richard Lomax (10 May 1944 – 15 September 2013) was an English guitarist and singer-songwriter. He is best known for his association with George Harrison, who produced Lomax''s recordings for the Beatles'' Apple record label in the late 1960s.', 'https://en.wikipedia.org/wiki/Jackie_Lomax', '2026-05-23 23:50:09', 1, 'Jackie Lomax', '["rock", "singer-songwriter", "60s", "70s", "england"]', 'John Richard ''Jackie'' Lomax (b. 10 May 1944, Wallasey, Merseyside, England) was a guitarist, singer/songwriter and a friend of George Harrison and Eric Clapton. Recordings The Undertakers Unearthed 1963-65 The Lomax Alliance and CBS Recordings 1966-1967 Is This What You Want? 1968-1969 Heavy Jelly 1970 Home Is In My Head 1971 Three 1972 White Lady /Badger 1974 Livin'' For Lovin'' 1976 Did You Ever Have That Feeling? 1977 True Voices (Various Artists) 1991 The Ballad of Liverpool Slim 2001 & 2004', '21161', '118026', 'https://www.last.fm/music/Jackie+Lomax');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Split System', 'e69fb405-fdea-4e9b-8274-85450cacf323', 'AU', NULL, '["garage punk", "garage rock", "punk", "punk rock"]', '["alternative", "garage punk", "garage rock", "melbourne", "punk", "punk rock"]', NULL, NULL, '2026-05-23 23:50:10', 16, 'Split System', '["Garage Punk", "punk rock", "australia", "rock", "australian"]', 'Split System are a punk/garage rock ''n roll band from Melbourne, Australia. They released one album (Vol.1 in 2022), an EP and a bunch of singles. Band members are Jackson Reid Briggs (vocals), Arron Mawson (guitar), Ryan Webb (guitar), Deon Slaviero (bass) and Mitch McGregor (drums).', '17091', '193818', 'https://www.last.fm/music/Split+System');
