INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jimi Hendrix Experience', '33b3c323-77c2-417c-a5b4-af7e6a111cc9', 'GB', 1966, '[]', '["hard rock", "soul", "united kingdom", "blues", "pop and chart", "uk", "english", "england", "rhythmic", "energetic", "british", "american", "sexual", "rock", "psychadelic", "blues rock", "jimi hendrix", "classic rock", "jam band", "psychedelic rock", "southern soul", "acid rock"]', NULL, NULL, '2026-05-23 17:38:25', 4, 'The Jimi Hendrix Experience', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Hierophants', '5f76d802-ae42-4a74-a8d9-7e85712420e2', 'AU', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:50:33', 29, 'Hierophants', '["anti-fade", "punk", "Garage Punk", "post-punk", "Videodrone"]', 'Hierophants are an Australian quartet who play jittery, nervous post-punk/new wave-inspired indie rock. Their simple, catchy songs feature buzzing organ and a thin layer of echo, along with lyrics expressing stress and frustration. Consisting of drummer Jake Robertson (also of Ausmuteants), guitarist Zak Olsen, keyboard player Paris Richens, and bassist Daff Gravolin, the group formed in 2010 after Olsen moved to the Southern Australian city of Geelong.', '27322', '151568', 'https://www.last.fm/music/Hierophants');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Nightshift', '8b43bc15-5dad-4ee2-93d7-469cb8d7bebb', 'GB', NULL, '["avant-garde", "experimental rock"]', '["avant-garde", "experimental rock"]', NULL, NULL, '2026-05-23 23:50:33', 13, 'Nightshift', '["west coast", "french pop", "indie pop", "soft rock", "glasgow"]', 'There has been more than one act called Nightshift.  1. Compton, USA producer Steve Espejo is the artist behind NIGHTSHIFT. Nightshift''s sound consist of beautiful melodies with dark undertones, chill, dark, experimental, and downtempo. NIGHTSHIFT will be releasing his first EP January 12, 2012 titled Postlapsaria.   2. Nightshift is hard rock band from Belgrade, Serbia. Members are: Milan Scepanovic-vocals, guitar, talkbox, e-bow; Danijel Scepanovic: drums, percussion; Marko Dacic: vocals, bass.', '26760', '208458', 'https://www.last.fm/music/Nightshift');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('L. Subramaniam', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:50:34', 1, 'L. Subramaniam', '["violin", "carnatic", "indian classical", "Indian", "world"]', 'A gifted South Indian counterpart of Jean-Luc Ponty on the electric violin, and endlessly curious about all kinds of music, Subramaniam has been a pioneer in exploring intelligent fusions between European classical music, American jazz, rock, and South Indian music. His father, a master Indian violinist, and mother, who played the Indian veena, were his first musical influences, and after abandoning a career in medicine, he formed a violin trio with his two brothers while still in India.', '29068', '165099', 'https://www.last.fm/music/L.+Subramaniam');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Fake Fruit', '61c35161-c45c-4779-ac23-0bac43633503', 'US', NULL, '["indie rock", "post-punk"]', '["indie rock", "post-punk"]', NULL, NULL, '2026-05-23 23:50:34', 10, 'Fake Fruit', '["indie pop", "indie rock", "post-punk", "Garage Rock", "Lo-Fi"]', 'Conceived in New York and raised in Vancouver, Fake Fruit has its roots in two artistically vibrant communities. Frontwoman Hanna Amato moved to Canada for a nannying job and brought her music with her, picking up Jess Lebenburg on lead guitar, Tom Waelen on drums, and Gabe Ragel on bass to keep the band going strong.', '41075', '310824', 'https://www.last.fm/music/Fake+Fruit');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jerry Lee Lewis', 'b59ac58d-036e-4bba-8112-c32a34c4575b', 'US', 1935, '[]', '["rock", "pop", "american", "blues", "singer-songwriter", "rockabilly", "country", "rock and roll", "honky tonk", "jerry lee lewis", "classic pop and rock", "rock & roll", "country gospel", "sun box", "2008 universal fire victim", "the best of jerry lee lewis", "[r12065312]"]', NULL, NULL, '2026-05-23 23:50:35', 4, 'Jerry Lee Lewis', '["rockabilly", "Rock and Roll", "rock n roll", "oldies", "classic rock"]', 'Jerry Lee Lewis (September 29, 1935 – October 28, 2022) was an American pianist, singer, and songwriter. He was a pioneer of rock and roll and rockabilly music and made his first recordings in 1952 at Cosimo Matassa''s J&M Studio in New Orleans, Louisiana, and in 1956 at Sun Records in Memphis, Tennessee. Lewis achieved commercial success with early recordings such as "Crazy Arms" and "Whole Lotta Shakin'' Goin'' On", followed by "Great Balls of Fire", "Breathless", and "High School Confidential".', '998686', '9527542', 'https://www.last.fm/music/Jerry+Lee+Lewis');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('A.M. Blue  September', 'f97b55a8-7d03-4ebe-a277-a9cadc2a9f86', 'SE', 1984, '[]', '["dance", "pop and chart"]', 'September is the ninth month of the year in the Julian and Gregorian calendars. Its length is 30 days.', 'https://en.wikipedia.org/wiki/September', '2026-05-23 16:57:04', 1, 'September', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Geoff Goddard & Kenny Hollywood', '4cbccfd5-bd76-46ff-9798-eac6cf1930d4', 'GB', 1937, '[]', '[]', 'Geoffrey Goddard (19 November 1937 – 15 May 2000) was an English songwriter, singer and instrumentalist. Working for Joe Meek in the early 1960s, he wrote songs for Heinz, Mike Berry, Gerry Temple, the Tornados, Kenny Hollywood, the Outlaws, Freddie Starr, Screaming Lord Sutch, the Ramblers and John Leyton. His song for Leyton, "Johnny Remember Me", reached number 1 in the UK Singles Chart.', 'https://en.wikipedia.org/wiki/Geoff_Goddard', '2026-05-23 16:57:05', 1, 'Geoff Goddard', NULL, NULL, NULL, NULL, NULL);
