INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Miles Davis Quintet', 'fe7245e7-d734-4ca1-8e26-691883f58201', 'US', 1955, '[]', '["jazz", "hard bop", "cool jazz", "jazzband"]', 'The Miles Davis Quintet was an American jazz band from 1955 to early 1969 led by Miles Davis. The quintet underwent frequent personnel changes toward its metamorphosis into a different ensemble in 1969. Most references pertain to two distinct and relatively stable bands: the First Great Quintet from 1955 to 1958, and the Second Great Quintet from late 1964 to early 1969, Davis being the only constant throughout.', 'https://en.wikipedia.org/wiki/Miles_Davis_Quintet', '2026-05-23 16:57:23', 1, 'Miles Davis Quintet', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Rites of Spring', 'b2ff1a6d-9198-4646-b068-8965242d245b', 'US', 1983, '[]', '["hardcore", "emo", "hardcore punk", "post-hardcore", "emocore", "revolution summer"]', NULL, NULL, '2026-05-23 16:57:39', 10, 'Rites of Spring', NULL, NULL, NULL, NULL, NULL);
