INSERT OR IGNORE INTO "artist_enrichment" VALUES('Brief Weeds', 'e75a88ed-288f-4011-b4b9-de1f47af26ab', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:50:40', 2, 'Brief Weeds', '["psychedelic", "indie", "indie rock", "rock", "Neo-Psychedelia"]', 'The Brief Weeds were Eddie Janney, Guy Picciotto and Brendan Canty of Rites Of Spring and Happy Go Licky and Mike Hampton of SOA, Faith, Embrace, Manifesto. Guy and Brendan were also in Fugazi. The Weeds line-up was also the band One Last Wish  They released A Very Generous Portrait 7" in 1990, Songs of Innocence and Experience 7" in 1992 and were featured on the International Pop Swing compilation CD on K Records in Olympia Washington.', '1088', '5723', 'https://www.last.fm/music/Brief+Weeds');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Alex Macfarlane', '4627eea6-8f41-4afb-b14b-43ec71f135be', 'AU', NULL, '[]', '[]', 'Alexander Macfarlane (1851–1913) was a Scottish logician, physicist, and mathematician.', 'https://en.wikipedia.org/wiki/Alex_Macfarlane', '2026-05-23 23:54:46', 5, 'Alex Macfarlane', '["ambient", "psychedelic"]', NULL, '1045', '5723', 'https://www.last.fm/music/Alex+Macfarlane');
