INSERT OR IGNORE INTO "artist_enrichment" VALUES('Pinch Points', '2f5a3772-3708-49d1-8993-0a1faa4479ac', 'AU', NULL, '["garage punk", "post-punk", "punk"]', '["garage", "garage punk", "post-punk", "punk"]', NULL, NULL, '2026-05-23 23:51:06', 6, 'Pinch Points', '["post-punk", "Garage Punk", "egg punk", "Crank wave", "Garage Rock"]', 'Pinch Points is a Post-Punk band from Melbourne, Australia .  Their 2018 debut EP ''Mechanical Injury'' earned worldwide acclaim, most notably being 1 of 4 Australian artists to be included in Bandcamp''s ''Best 100 releases of 2018'' list.  https://pinchpoints.bandcamp.com/album/mechanical-injury', '7201', '93255', 'https://www.last.fm/music/Pinch+Points');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Kid Congo Powers w/ Subsonics', '46c5862a-ccbb-4bd9-8c48-2d8d992e38f3', 'US', 1959, '[]', '[]', 'Brian Tristan (born March 27, 1959), better known by his stage name Kid Congo Powers, is an American rock guitarist, singer, and actor best known as a member of the Gun Club, the Cramps and Nick Cave and the Bad Seeds. He has also played with the Divine Horsemen, the Angels of Light, Die Haut, and Knoxville Girls.', 'https://en.wikipedia.org/wiki/Kid_Congo_Powers', '2026-05-23 17:00:12', 2, 'Kid Congo Powers', NULL, NULL, NULL, NULL, NULL);
