INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Unknowns', '38fc5a51-868e-4534-a61f-f4909219990e', 'US', 1980, '[]', '["rock"]', NULL, NULL, '2026-05-23 23:51:16', 7, 'The Unknowns', '["punk", "80s", "Garage Rock", "rock", "rhythm and blues"]', 'Check https://theunknowns4.bandcamp.com/  The Unknowns are a 4 piece rock/pub punk band from Brisbane Australia. Consisting of Josh Hardy (The Chats), Tom, Nathan Montgomery and Eamon Sandwith (The Chats), formed in 2014.', '8352', '70804', 'https://www.last.fm/music/The+Unknowns');
