INSERT OR IGNORE INTO "artist_enrichment" VALUES('Billy Strange', '9bfecfa4-0908-4842-b7bb-617f38532bb7', 'US', 1930, '[]', '["session"]', NULL, NULL, '2026-05-23 23:51:18', 1, 'Billy Strange', '["guitar", "instrumental", "All", "rock", "rockabilly"]', 'William Everett "Billy" Strange (September 29, 1930 – February 22, 2012) was an American singer, songwriter, guitarist, and actor. He was a session musician with the famed Wrecking Crew, and was inducted into the Musicians Hall of Fame and Museum as a member of The Wrecking Crew in 2007.  Billy Strange was born in Long Beach, California on September 29, 1930. Strange teamed up with Mac Davis to write several hit songs for Elvis Presley including "A Little Less Conversation", the theme from Charro!, and "Memories".', '11619', '65377', 'https://www.last.fm/music/Billy+Strange');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Kip Tyler & The Flips', '56de0a52-6063-4304-a202-cf8b69045954', 'US', 1956, '[]', '[]', NULL, NULL, '2026-05-23 23:51:18', 1, 'Kip Tyler & The Flips', '["rockabilly", "rock", "classic rock", "blues", "Rock and Roll"]', 'Kip Tyler (real name: Elwood Westertson Smith; born May 31, 1929 Chicago, Illinois; died September 23, 1996, Los Angeles, California) was American rock and roll singer and bongo player. His backing band was called The Flips, their line up was Jim Horn, Larry Knechtel, Mike Bermani, Mike Deasy, Sandy Nelson and Steve Kreisman.  Kip Tyler was lead singer of Sleepwalkers during his time at Union High School and later teamed up with rival musicians from Fairfax High School to form the early version of Kip Tyler and the Flips.', '1071', '3791', 'https://www.last.fm/music/Kip+Tyler+&+The+Flips');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Letting Up Despite Great Faults', '9a7192b7-38a9-48de-8a6b-a72cd406ceac', 'US', 2004, '["dream pop", "indie pop", "indie rock", "indietronica", "shoegaze", "twee pop"]', '["dream pop", "dreampop", "indie pop", "indie rock", "indiepop", "indietronica", "shoegaze", "synthpop", "twee pop"]', NULL, NULL, '2026-05-23 23:51:19', 4, 'Letting Up Despite Great Faults', '["shoegaze", "dream pop", "indie", "indie pop", "indietronica"]', 'Letting Up Despite Great Faults is the indie electro-based sonic diary of founding member Mike Lee. Their 2009 self-titled debut LP was an exploration of indiepop melodies, electro beats, and shoegaze guitars. The lead single "In Steps" instantly caught the attention of everyone from Pitchfork to Rolling Stone. With rave reviews and countless blog support, 2011 saw the release of Paper Crush, an EP full of washed synths, hazy guitars, and heartfelt pop that NPR called "both nostalgic and caught in a moment that feels never-ending.', '106856', '1619894', 'https://www.last.fm/music/Letting+Up+Despite+Great+Faults');
