INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jacques Thollot', '4525994d-76eb-4ea5-840b-871c4b7716e6', 'FR', 1946, '[]', '["jazz"]', NULL, NULL, '2026-05-23 23:51:25', 1, 'Jacques Thollot', '["jazz", "experimental", "french", "Progressive rock", "avant- garde"]', 'Brilliant jazz drummer that released a series of solo LP''s in the 70''s.  Additionally, he''s played with Sam Rivers, Sonny Sharrock, Don Cherry, Steve Lacy and other greats in the past.', '2608', '34154', 'https://www.last.fm/music/Jacques+Thollot');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Other Half', '0fea6e31-2e94-4b26-9225-486686d28205', NULL, 1966, '[]', '["psychedelic rock", "garage rock"]', 'The Other Half may refer to:', 'https://en.wikipedia.org/wiki/The_Other_Half', '2026-05-23 23:51:25', 3, 'The Other Half', '["Garage Rock", "Psychedelic Rock", "60s", "psychedelic", "garage"]', 'This obscure San Francisco ''60s band gained a degree of notoriety in the ''80s when their punk-garage single "Mr. Pharmacist" was included on one of Rhino''s Nuggets compilations and covered by the Fall. Actually, most of the Other Half''s material was far less garage than psychedelic, featuring the sustain-laden guitar of Randy Holden, one of the best Jeff Beck-inspired axemen of the ''60s. Boasting a just-out-of-the-garage approach to Haight-Ashbury psychedelia', '19160', '94975', 'https://www.last.fm/music/The+Other+Half');
