INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jett Powers', '17df698b-f224-48d5-bb78-81aaee753690', 'US', 1938, '[]', '[]', NULL, NULL, '2026-05-23 23:51:27', 1, 'Jett Powers', '["rockabilly", "All", "Rock and Roll", "60s", "classic rock"]', 'P.J. Proby (born James Marcus Smith, November 6, 1938) is an American singer, songwriter, and actor. Given the stage name Jett Powers by top Hollywood agents Gabey, Lutz, Heller and Loeb, he took acting and singing lessons, and appeared in movies with small roles. Two singles, "Go, Girl, Go" and "Loud Perfume", were released on an independent label.   He has portrayed Elvis Presley and Roy Orbison in musical theater productions and had a recording career in his own right.', '4859', '15702', 'https://www.last.fm/music/Jett+Powers');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Frank Zappa', 'e20747e7-55a4-452e-8766-7b985585082d', 'US', 1940, '[]', '["rock", "electronic", "classical", "progressive rock", "jazz", "american", "orchestral", "experimental", "jazz rock", "composer", "psychedelic rock", "blues rock", "jam band", "art rock", "spoken word", "experimental rock", "pop rock", "jazz fusion", "big band", "comedy rock", "avant-garde", "jazz-rock", "rock opera", "field recordings", "satire", "sound collage", "film soundtrack", "rock and indie", "modern classical", "musique concr\u00e8te", "avant-prog", "doo-wop", "death by prostate cancer", "rock & roll", "pop/rock", "speeches", "rhino", "synclavier music", "server name", "weird america", "vyrzukhisuc-artiest"]', NULL, NULL, '2026-05-23 23:51:27', 6, 'Frank Zappa', '["Progressive rock", "experimental", "jazz", "rock", "classic rock"]', 'Frank Vincent Zappa (born December 21, 1940 in Baltimore, Maryland, United States – December 4, 1993 in Los Angeles, California, United States) was an American composer, guitarist, singer, bandleader and producer. He was one of the most prolific musicians of his time, releasing over fifty albums of original material spanning over a thirty-five year career.  Zappa''s earliest influences were 1950s pop and rock (such as doo-wop and rhythm and blues), and 20th-century classical composers including Igor Stravinsky and Edgard Varèse.', '1335984', '67145644', 'https://www.last.fm/music/Frank+Zappa');
