INSERT OR IGNORE INTO "artist_enrichment" VALUES('Musical Linn Twins', 'bf8f0324-096f-45c9-9046-a8ff1c02bf3f', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 17:03:51', 2, 'The Musical Linn Twins', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Hygiene', 'db4f1d61-0834-4f7f-8ffc-305eb0e7f69d', NULL, NULL, '[]', '[]', 'Hygiene is a set of practices performed to preserve health.', 'https://en.wikipedia.org/wiki/Hygiene', '2026-05-23 23:55:14', 2, 'Hygiene', '["Lo-Fi", "punk", "hardcore", "powerviolence", "Garage Punk"]', 'London lo-fi scuzziness reviving the spirits of Wire, Swell Maps and The Homosexuals.  www.myspace.com/hygieneldn  The new LP seems to be an improvement on the first, hopefully available on bandcamp soon. Public Sector here:   https://lavidaesunmus.bandcamp.com/album/public-sector-lp  Or there''s always the ''hardcore'' of the Australian Hygiene if that''s your bag.    In fact the punky Vancouver, British Columbia Hygiene might actually trump the pair of ''em depending on what mood you''re in. Find them here:', '1612', '20186', 'https://www.last.fm/music/Hygiene');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Rare Essence', '20c9cbaf-1014-45c3-a13f-289a3317f81d', NULL, 1976, '[]', '["the wickedest band alive"]', 'Rare Essence is a Washington, D.C.–based go-go band formed in 1976. Rare Essence has been amongst the most prominent musicians of the D.C. music scene, producing numerous hit songs in the local D.C. market and several hits nationwide, including the charting hit "Work the Walls".', 'https://en.wikipedia.org/wiki/Rare_Essence', '2026-05-23 23:55:14', 1, 'Rare Essence', '["All", "funk", "Go-Go", "DC", "gogo"]', 'Rare Essence, affectionately known by their fans as "THE WICKEDEST BAND ALIVE", grew from a relationship between four childhood friends: Quinten "Footz" Davidson, Andre "Whiteboy" Johnson, Michael "Funky Ned" Neal and John Jones. After school, the four young musicians would get together in each other''s basements and play top forty hits from such influential bands like Parliament/Funkadelic, Cameo, and Confunkshun. Eventually the band adapted more players and conformed to the go-go sound that started in 1976.', '12135', '67568', 'https://www.last.fm/music/Rare+Essence');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('William Bell', 'd9c9cfb7-f751-4fb0-97c0-b3ddd768bc78', 'US', 1939, '[]', '["soul", "rock and indie", "r&b"]', 'William or Willie Bell may refer to:', 'https://en.wikipedia.org/wiki/William_Bell', '2026-05-23 23:55:15', 2, 'William Bell', '["soul", "stax", "rhythm and blues", "funk", "Southern Soul"]', 'William Bell (born 16 July 1939) is an American soul singer and songwriter. As a performer, he is probably best known for his debut single 1961''s "You Don''t Miss Your Water" and 1968''s top 10 hit in the UK "Private Number", a duet with Judy Clay.  One of the finest of the Stax/Volt soul artists, he was, like Otis Redding, able to tell a story with great sincerity and  flawless musicality.  His song "You Don''t Miss Your Water (''Til Your Well Runs Dry)" is a Memphis masterpiece.', '388729', '2141454', 'https://www.last.fm/music/William+Bell');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Waxahatchee', '42321e24-42b6-4f08-b0d9-8325ee887a20', 'US', 1989, '["alternative country", "alternative rock", "americana", "folk", "indie folk", "indie rock", "singer-songwriter", "slacker rock"]', '["acoustic", "alternative", "alternative country", "alternative rock", "americana", "female vocalists", "folk", "indie", "indie folk", "indie rock", "singer-songwriter", "slacker rock"]', 'Waxahatchee is an American indie music project, formed in 2010 by American singer-songwriter Kathryn Crutchfield (born January 4, 1989), known professionally as Katie Crutchfield, following the breakup of her previous band P.S. Eliot. The band is named after Waxahatchee Creek in Alabama, where Crutchfield grew up. Originally an acoustic solo project, her recordings now tend to involve a full backing band.', 'https://en.wikipedia.org/wiki/Waxahatchee', '2026-05-23 23:55:15', 3, 'Waxahatchee', '["singer-songwriter", "indie", "female vocalists", "alternative", "acoustic"]', 'Waxahatchee is a solo project of American singer and guitarist Katie Crutchfield (born in 1989) of P.S. Eliot and Bad Banana.  Waxahatchee, named after Waxahatchee Creek in Alabama where Crutchfield grew up, began in 2010 during the breakup of P.S. Eliot. Crutchfield released her first music as Waxahatchee as a split cassette with Chris Clavin on Plan-It-X Records. Her bedroom-recorded debut album, American Weekend, was released on Don Giovanni Records in 2012.', '476568', '19251225', 'https://www.last.fm/music/Waxahatchee');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Pipiolas', '63cce5fc-3cbc-4f4d-b113-82154ba6f0bb', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:55:16', 4, 'Pipiolas', '["spanish", "indie", "spain"]', 'Formed by Adriana Ubani Álvarez (1997, from Las Palmas de Gran Canaria) and Paula Reyes Morillas (1995, Alcorcón), PIPIOLAS is a duo with two radically charismatic people. But even more important is their overwhelmingly artistic spirit. They have that “certain something” that makes them stand out from the crowd. They are what makes them special.', '10266', '201005', 'https://www.last.fm/music/Pipiolas');
