INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Nobles', '860143b0-5398-490d-ab49-4cf2496d87ed', 'US', NULL, '[]', '[]', 'The Nobles is a series of novels by David Cook, Victor Milán, Mark Anthony, Brian Thomsen, Paul Kidd, and Lynn Abbey, set in the Forgotten Realms campaign setting.', 'https://en.wikipedia.org/wiki/The_Nobles', '2026-05-23 23:55:25', 1, 'The Nobles', '["60s", "80s", "classic rock", "Garage Rock", "70s"]', NULL, '3229', '10036', 'https://www.last.fm/music/The+Nobles');
