INSERT OR IGNORE INTO "artist_enrichment" VALUES('High Tension', '66b22cb8-4b03-409d-ab24-c0b20d621601', 'DE', 1982, '[]', '[]', NULL, NULL, '2026-05-23 23:55:35', 9, 'High Tension', '["heavy metal", "hardcore", "d-beat", "metal", "hard rock"]', 'There are 4 artists that share this name  1:  Australian post-hardcore group. Featuring members of Young & Restless, The Nation Blue, Love Like Electrocution & Heirs  2: German Heavy Metal band from Villingen-Schwenningen formed in 1980.  3: High Tension - An electronic music duo  Since 1996 the 2 Dutch amature producers X-ecute and Fennek stopped competing each other and teamed up. High Tension was born. In that time hardcore or gabber music was our thing.', '12737', '156728', 'https://www.last.fm/music/High+Tension');
