INSERT OR IGNORE INTO "artist_enrichment" VALUES('Baby Mullet', '9aed7b5b-3f56-465a-9ce9-cb86e66758af', 'AU', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:55:39', 2, 'Baby Mullet', '["punk", "rock", "alternative rock", "punk rock", "riot grrrl"]', 'Baby Mullet are a three piece female fronted rock band from Melbourne. Their punchy and unapologetic tracks are fuelled by topics such as cat calling, sex and just not giving a fuck! - Triple J Unearthed', '1260', '11696', 'https://www.last.fm/music/Baby+Mullet');
