INSERT OR IGNORE INTO "artist_enrichment" VALUES('Problem Patterns', 'fb2498be-b0e9-411e-91d4-96339a579ea1', 'GB', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:55:44', 6, 'Problem Patterns', '["riot grrrl", "queercore", "Heavy Punk", "Crank wave", "egg punk"]', 'Problem Patterns is a four-piece punk band from Belfast, Northern Ireland, formed in 2018.  The band is comprised of Beverley Boal, Bethany Crooks, Ciara King and Alanah Smith. They have no front person, and often switch musical roles in an effort to amplify all voices and viewpoints evenly.  http://problempatterns.bandcamp.com', '15139', '98883', 'https://www.last.fm/music/Problem+Patterns');
