INSERT OR IGNORE INTO "artist_enrichment" VALUES('Tiger Pussy', 'd5430948-ba5b-4f3a-abc6-4fc6ee815870', 'PH', 2008, '[]', '[]', NULL, NULL, '2026-05-23 23:55:48', 14, 'Tiger Pussy', '["philippines", "punk", "riot grrrl", "riot grrl", "Cebu"]', '“Energy” hardly does justice to this punk rock group featuring Jan Sunday on vocals, Banjo on guitars, Shak on bass, and King on drums. With their fast-paced live performances and two half-hour albums in tow, the band has gained an audience in both the Cebu and Manila punk scenes, easily making them an act you just can’t miss.  https://tigerpussyx.bandcamp.com/', '779', '8656', 'https://www.last.fm/music/Tiger+Pussy');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Trinity', '2ec5ba02-58fe-44b3-add2-e1151109c190', 'JM', 1954, '[]', '["reggae", "dancehall"]', NULL, NULL, '2026-05-23 23:55:49', 1, 'Trinity', '["reggae", "Drum and bass", "dub", "trance", "eurodance"]', 'There are at least eighteen artists/groups that have released music under the name Trinity:  1) Deejay Trinity, born Wade Brammer, February 10, 1954 in Kingston, was a dub producer and DJ.  2) Trinity is a Dutch pop/folk band, playing christian music with Latin and Irish influences. Their songs are mainly in Spanish, English and Dutch. Trinity''s roots are in Peru, where the three Smelt brothers (Elbert, Johan, Niek) lived when they were children. Back in the Netherlands they formed the band Trinity', '75262', '644329', 'https://www.last.fm/music/Trinity');
