INSERT OR IGNORE INTO "artist_enrichment" VALUES('VVV', '15601705-e97d-42cc-aa22-a2d1cf751f0a', NULL, NULL, '[]', '["uk garage", "dubstep", "drum and bass", "sillyname"]', 'VVV may refer to:', 'https://en.wikipedia.org/wiki/VVV', '2026-05-23 23:56:04', 3, 'VVV', '["dubstep", "future garage", "2-step", "UK Garage", "Post-garage"]', 'There are multiple artists named VVV:  1). Iranian born dubstep/futuregarage/ukgarage producer & musician out of Austin, TX (real name Shawhin Izaddoost).  https://soundcloud.com/vvv  2). VVV, better known as  VVV Trippin''you, is a group of Spanish Bakalao, originally from Madrid (Spain). The group consists of 3 members, Adrián, Elinor, Salvi and Manu (2015-???).  3). Pan Sonic and Suicide main-man Alan Vega collaboration.  In the early 1970s Alan Vega cofounded Suicide', '29272', '305282', 'https://www.last.fm/music/VVV');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Tom Araya', '362105d1-8f4f-4ba1-949f-3e70183880b5', 'US', 1961, '[]', '["american", "metal", "thrash metal"]', NULL, NULL, '2026-05-23 23:56:04', 3, 'Tom Araya', '["thrash metal", "metal", "limited tracks", "punk", "alternative"]', 'Tom Araya (born Tomás Enrique Araya June 6, 1961 in Valparaíso, Chile) is the vocalist and bassist of the American thrash metal band Slayer. Araya''s family moved to the United States in 1966, and at the age of eight picked up the bass guitar, playing Beatles and Rolling Stones songs with his older brother, who played the guitar. Araya was employed as a respiratory therapist in the early 1980s, using his earnings to finance Slayer''s debut album Show No Mercy.', '5099', '16260', 'https://www.last.fm/music/Tom+Araya');
