INSERT OR IGNORE INTO "artist_enrichment" VALUES('Collate', '62348c47-3f01-42a7-9d7f-d310b84a1c7c', NULL, NULL, '[]', '[]', 'Collation is the assembly of written information into a standard order. Many systems of collation are based on numerical order or alphabetical order, or extensions and combinations thereof. Collation is a fundamental element of most office filing systems, library catalogs, and reference books.', 'https://en.wikipedia.org/wiki/Collate', '2026-05-23 23:56:09', 9, 'Collate', '["noise", "punk", "experimental", "american", "portland"]', 'This three-member punk band out of Portland makes super-catchy, lo-fi punk, and it’s a whole lot of fun. Expect simple but dark basslines, scratchy stabs of guitar and a mix of male and female vocals.  https://collate.bandcamp.com/', '549', '6147', 'https://www.last.fm/music/collate');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Knifeplay', '2eaa7d46-4bb7-4808-aade-5e33c72896e9', 'US', 2017, '[]', '["shoegaze", "dream pop", "slowcore", "indie rock"]', NULL, NULL, '2026-05-23 23:56:10', 10, 'Knifeplay', '["shoegaze", "dream pop", "slowcore", "Lo-Fi", "indie"]', 'Knifeplay is a Philly-based slowcore band, led by lead singer/ringleader, TJ Strohmer. Knifeplay''s bleak lyrics are difficult to swallow, but they’re clouded in a mask of beauty and shimmering shoegaze haze – perhaps by design; escaping hurt through any means possible, even if it means hurting another.', '125819', '1784651', 'https://www.last.fm/music/Knifeplay');
