INSERT OR IGNORE INTO "artist_enrichment" VALUES('Cozy Cole', '7fc949db-cc94-4196-ac79-245471930008', 'US', 1909, '[]', '["jazz", "swing"]', NULL, NULL, '2026-05-23 23:56:34', 1, 'Cozy Cole', '["jazz", "swing", "drums", "Need to Rate", "40s"]', 'Cozy Cole (October 17, 1909 – January 9, 1981) was an American jazz drummer who scored a #1 Cashbox magazine hit with the record "Topsy Part 2" (also known as "Topsy II", "Topsy 2", and so on). That song peaked at number three on Billboard Hot 100 and at number one on the R&B chart. It sold over one million copies and was awarded a gold disc. The track, which also peaked at #29 in the U.K. Singles Chart in 1958, contained a lengthy drum solo and was one of the few drum solo recordings that ever made the Billboard Hot 100.', '11576', '59780', 'https://www.last.fm/music/Cozy+Cole');
