INSERT OR IGNORE INTO "artist_enrichment" VALUES('Lux Interior', '58856f5c-0589-4811-9441-c08a077d4bd9', 'US', 1946, '[]', '[]', NULL, NULL, '2026-05-23 23:56:35', 1, 'Lux Interior', '["srs", "lux"]', 'Erick Lee Purkhiser (October 21, 1946 – February 4, 2009), better known as Lux Interior, was an American singer and a founding member of the legendary garage punk band The Cramps from 1976 until his sudden death in February 2009 aged 62.', '178', '1372', 'https://www.last.fm/music/Lux+Interior');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Fake Names', 'a4271e33-8969-4dd8-9e3c-88b269e89fe0', NULL, 2016, '[]', '[]', NULL, NULL, '2026-05-23 23:56:35', 30, 'Fake Names', '["punk", "punk rock", "pop punk", "hardcore", "hardcore punk"]', 'Fake Names is an American hardcore and punk rock super group, comprising of members from various old school punk and hardcore bands. They released two albums to date: Fake Names (2019) and Expendables (2023). Personnel: Brian Baker (of Minor Threat, Bad Religion and Dag Nasty), Michael Hampton (of S.O.A. and Embrace), Dennis Lyxzén (of Refused, INVSN and The [International] Noise Conspiracy), Johnny Temple (of Girls Against Boys and Soulside) and, their latest member, Brendan Canty (of Fugazi and Rites of Spring).', '16079', '156710', 'https://www.last.fm/music/Fake+Names');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Dippers', 'dc15cdb7-175d-4c21-ba8c-4b2b70160086', NULL, 2012, '[]', '[]', 'Dippers are members of the genus Cinclus in the bird family Cinclidae, so-called because of their bobbing or dipping movements.  They are unique among passerines for their ability to dive and swim underwater.', 'https://en.wikipedia.org/wiki/Dippers', '2026-05-23 23:48:20', 3, 'Dippers', '["punk", "Garage Rock", "hardcore", "indie rock", "noise rock"]', 'The artist formerly known as Thigh Master', '826', '6148', 'https://www.last.fm/music/Dippers');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Toads', 'f8a8c385-c70b-415b-91a3-99e752ae23f4', 'GB', 1977, '[]', '["uk", "punk", "norfolk", "norwich", "england"]', NULL, NULL, '2026-05-23 23:56:36', 6, 'The Toads', '["surf rock", "Surf", "UK", "indie rock", "Rock and Roll"]', 'The Toads were a punk band from Norwich, UK formed in February 1977 and disbanded in 1978. The band never had any releases, but a demo and various other recordings are available from their website http://www.toads1977.co.uk/index.php  Band members were Dave Smith guitar, bass & vocals, Dave Viner guitar & vocals, Paul Cheetham guitar & vocals, Polo (Alan Pollard) drums.  Dave Smith & Polo were later  members of Broadside Outcasts & Silent Noise Paul Cheetham later formed The Dr Space Toad Experience', '1798', '12272', 'https://www.last.fm/music/The+Toads');
