INSERT OR IGNORE INTO "artist_enrichment" VALUES('YL Hooi', '2de39405-d1ca-4dd7-900d-d042fc006e45', 'AU', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:56:47', 4, 'YL Hooi', '["dub", "electronic", "post-punk", "psychedelic", "australia"]', 'YL Hooi, a.k.a. Ying-Li Hooi, is an Australian artist. She released her debut album "Untitled" on cassette in 2019. It was re-released on vinyl in 2021.', '11252', '62959', 'https://www.last.fm/music/YL+Hooi');
