INSERT OR IGNORE INTO "artist_enrichment" VALUES('Vacuum', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:56:51', 1, 'Vacuum', '["synthpop", "pop", "electronic", "swedish", "90s"]', 'There is more than one band called Vacuum:  1) a Czech death/doom metal band 2) a Swedish syntpop formation 3) a Dutch punk band (see Vacuüm) 4) an Italian black metal act 5) a Chilean powerviolence band 6) a New Zealand early punk band Bill Direen (guitar,vocals) Stephen Cogle (bass,vocals)      Peter Stapleton (drums) Brendan Arnold (percussion & vocals) Peter Fryer (organ)      Allen Meek (organ) 1978 - 1979 6) A Swedish punk rock band  1) Vacuum', '56869', '929032', 'https://www.last.fm/music/Vacuum');
