INSERT OR IGNORE INTO "artist_enrichment" VALUES('Afrirampo', '35a8b7b9-8b10-4e9f-ac77-a899d75510a9', 'JP', 2002, '[]', '["jazz"]', NULL, NULL, '2026-05-23 23:56:54', 1, 'Afrirampo', '["noise rock", "japanese", "experimental", "Avant-Garde", "noise"]', 'Afrirampo (あふりらんぽ) are a band from Osaka, Japan that was founded in 2002.  They are Oni (guitar, vocals) and Pikachu (drums, vocals). Since forming in 2002 they have toured with Sonic Youth and Lightning Bolt, collaborated with Acid Mothers Temple and released several CDs on various labels. In 2005 they performed at All Tomorrow''s Parties, the avant-garde music festival curated by Vincent Gallo, and joined performance artist Yoko Ono on stage for her closing piece.', '26892', '371502', 'https://www.last.fm/music/Afrirampo');
