INSERT OR IGNORE INTO "artist_enrichment" VALUES('Alex Cameron', '0eabad49-1814-453a-8555-8a21edfbf0f4', 'AU', 1990, '[]', '["indie"]', NULL, NULL, '2026-05-23 23:57:04', 23, 'Alex Cameron', '["synthpop", "australian", "soft rock", "new wave", "minimal synth"]', 'Solo project of Alex Cameron, known as a member of Australian electronic group Seekae.  Released his debut album ''Jumping The Shark'' for free on his website on November 22, 2013.', '193513', '5109091', 'https://www.last.fm/music/Alex+Cameron');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('High Rise', '2f3eb5a0-d7f6-4baf-9db0-9f15bd0999aa', 'JP', 1984, '[]', '["psychedelic rock", "noise rock", "heavy psych"]', NULL, NULL, '2026-05-23 23:57:05', 4, 'High Rise', '["noise rock", "Psychedelic Rock", "psychedelic", "japanese", "noise"]', 'There are two bands with this name:  1) Psychedelic acid rock-band from Japan. High Rise is an explosive power trio comprised of bassist/vocalist asahito nanjo (南条麻人), guitarist Munehiro Narita, and a succession of drummers that has included Yuro Ujiie and Pill in the past and free-improv veteran Shoji Hano at present. High Rise mixes the jazz-influenced improvising of Cream with the brutal amphetamine-inspired rock of Blue Cheer. Narita is one of rock’s unsung guitar players', '25150', '369310', 'https://www.last.fm/music/High+Rise');
