INSERT OR IGNORE INTO "artist_enrichment" VALUES('Bo Diddley', 'bf659d74-0b61-488c-8a7d-594f43bed9e0', 'US', 1928, '[]', '["rock", "american", "blues", "funk", "blues rock", "rock and roll", "electric blues", "rock and indie", "death by heart failure", "r&b", "rock & roll", "rhythm & blues", "2008 universal fire victim"]', NULL, NULL, '2026-05-23 23:56:13', 3, 'Bo Diddley', '["blues", "rhythm and blues", "Rock and Roll", "rock", "soul"]', 'Ellas Bates McDaniel (December 30, 1928 – June 2, 2008), known professionally as Bo Diddley, was an American guitarist, singer, and songwriter who played an important role in the transition from blues to rock and roll. He influenced a wide range of artists, including Buddy Holly, the Beatles, the Rolling Stones, the Animals, George Thorogood, Syd Barrett, Tom Petty, and the Clash.  Diddley was known for incorporating African-inspired rhythms into his music', '637177', '5714895', 'https://www.last.fm/music/Bo+Diddley');
