INSERT OR IGNORE INTO "artist_enrichment" VALUES('Set-Top Box', '3bc89aab-0d51-4e40-b3f2-7cea40834b57', NULL, NULL, '[]', '[]', 'A set-top box (STB), also known as a cable box, receiver, or simply box, and historically television decoder or a converter, is an information appliance device that generally contains a TV tuner input and displays output to a television set, turning the source signal into content in a form that can then be displayed on the television screen or other display device. It is designed to be placed alongside or "on top" (hence the name) of a television set.', 'https://en.wikipedia.org/wiki/Set-Top_Box', '2026-05-23 23:57:15', 7, 'Set-Top Box', '["egg punk"]', NULL, '2431', '20534', 'https://www.last.fm/music/Set-Top+Box');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Charles M. Bogert + Frog Army', '11b80336-72fd-4748-b657-43bc3c139e01', 'US', 1908, '[]', '[]', 'Charles Mitchill Bogert (June 4, 1908 – April 10, 1992) was an American herpetologist, and curator of herpetology and researcher for the American Museum of Natural History.', 'https://en.wikipedia.org/wiki/Charles_Bogert', '2026-05-23 17:16:10', 1, 'Charles Bogert', NULL, NULL, NULL, NULL, NULL);
