INSERT OR IGNORE INTO "artist_enrichment" VALUES('Frankie Ford', '3de70801-1c29-4667-9400-56c6e1061bcc', 'US', 1939, '[]', '["r&b", "new orleans r&b"]', NULL, NULL, '2026-05-23 23:57:23', 3, 'Frankie Ford', '["oldies", "rhythm and blues", "rock n roll", "Rock and Roll", "60s"]', 'Frankie Ford (August 4, 1939 – September 28, 2015), was an American rock and roll and rhythm and blues singer, best known for his 1959 hit "Sea Cruise".  He was born in Gretna, Louisiana, as Vincent Francis Guzzo, across the Mississippi River from New Orleans, and was the adopted son of Vincent and Anna Guzzo, who named him Vincent Francis Guzzo, Jr. He learned to sing and dance at an early age, and when at high school joined a group, the Syncopators, as singer and pianist.', '41222', '144774', 'https://www.last.fm/music/Frankie+Ford');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Young Marble Giants', '3d113367-769f-4200-9ff8-e19d47def451', 'GB', 1979, '[]', '["lo-fi", "rough trade", "diy", "minimal wave", "minimal", "alternative", "wales", "punk", "welsh", "british", "classic pop and rock", "uk", "post-punk", "indie pop"]', NULL, NULL, '2026-05-23 23:57:23', 4, 'Young Marble Giants', '["post-punk", "new wave", "80s", "indie", "indie pop"]', 'Young Marble Giants was a post-punk band from Cardiff, Wales, a trio formed in 1978. They consisted of Alison Statton (vocals), Stuart Moxham (guitar) and Phillip Moxham (bass), occasionally joined by keyboardist Peter Joyce.  They made one great album, Colossal Youth (1980), on Rough Trade, recorded very cheaply often using the first take. Extremely low-tech drum machine effects and home made synthesizers featured.  Alison Statton and Philip Moxham later worked as Weekend.', '251583', '4621468', 'https://www.last.fm/music/Young+Marble+Giants');
