INSERT OR IGNORE INTO "artist_enrichment" VALUES('Lace Curtain', 'fe574fad-bf5c-4397-a83a-ac81e06479c0', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:57:51', 1, 'Lace Curtain', '["australia", "electronic", "discover", "synth pop", "House"]', 'project featuring Mikey Young (Total Control, Eddy Current Suppression Ring, Ooga Boogas), James Vinciguerra (Total Control) and David West (Rat Columns). EP out on DFA records.', '3632', '22220', 'https://www.last.fm/music/Lace+Curtain');
