INSERT OR IGNORE INTO "artist_enrichment" VALUES('Blonde Redhead', '6821bf3f-5d5b-4b0f-8fa4-79d2ab2d9219', 'US', 1993, '[]', '["alternative rock", "nuno", "4ad", "rock and indie", "am\u00e9ricain", "usa", "indie rock", "american"]', NULL, NULL, '2026-05-23 23:57:52', 4, 'Blonde Redhead', '["indie", "indie rock", "alternative", "female vocalists", "rock"]', 'Blonde Redhead is an alternative rock band originating from New York City in the early 1990s. It was formed by Kazu Makino, Maki Takahashi and Milan-born Italian twin brothers Simone Pace and Amedeo Pace. They take their name from a song by DNA, a 70''s and 80''s no wave band from New York. Blonde Redhead caught the attention of Sonic Youth''s drummer, Steve Shelley, who produced their first self titled album in 1993. Shortly afterwards Maki Takahashi left the band and the remaining band members continued as a trio.', '1440303', '44277481', 'https://www.last.fm/music/Blonde+Redhead');
