INSERT OR IGNORE INTO "artist_enrichment" VALUES('Krimi', '485fccd1-f5b6-4d02-8311-6d4ed0f7ed64', 'AU', NULL, '[]', '[]', 'Edgar Wallace (1875–1932) was a British novelist, playwright and screenwriter whose works have been adapted for the screen on many occasions. His films fall into two categories, British adaptations and the German "Krimi" films.', 'https://en.wikipedia.org/wiki/Krimi', '2026-05-23 23:58:09', 5, 'Krimi', '[]', NULL, '222', '5991', 'https://www.last.fm/music/krimi');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Diseño Corbusier', '8659bfaa-6c81-4eb3-81e0-26359c68ddcf', NULL, NULL, '[]', '["ebm", "experimental", "minimal synth", "industrial"]', NULL, NULL, '2026-05-23 23:58:10', 1, 'Diseño Corbusier', '["minimal synth", "industrial", "spanish", "experimental", "Cassette Culture"]', 'Diseño Corbusier is the avant-garde electronics duo of Javier G. Marín and Ani Zinc, formed in Granada, Spain 1981. Like Sheffield’s relation to London during the punk explosion in the UK, Granada developed an experimental music scene 400 kilometers south of Madrid. As a child, there were no records in Ani’s house, so she grew up listening to the radio and was hypnotized after hearing ‘Remember Love’, by Yoko Ono. While attending university in Granada she responded to an ad in a music magazine by Javier', '2413', '19871', 'https://www.last.fm/music/+noredirect/Dise%C3%B1o+Corbusier');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Limp', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:58:10', 1, 'The Limp', '["minimal synth", "post-punk", "minimal wave", "minimal electronic", "australian"]', 'Australian post-punk outfit. 1979-82. Originated in Newcastle, Australia. Two singles "Marked Man" and "Animal Kingdom", one track on "A Selection" (M Squared Compilation).', '2082', '11333', 'https://www.last.fm/music/The+Limp');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Thee Fine Lines', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:58:12', 1, 'Thee Fine Lines', '["punk", "rock", "Garage Punk", "Garage Rock", "springfield"]', 'Thee Fine Lines play raw rock & roll music. They played their first show on Halloween 2001 and continue to release records and play shows in 2010.', '1304', '8838', 'https://www.last.fm/music/Thee+Fine+Lines');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Linda Lindas', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:58:13', 1, 'The Linda Lindas', '["riot grrrl", "punk", "punk rock", "Garage Punk", "female vocalists"]', 'The Linda Lindas is a four piece punk band from California, USA. Two sisters, a cousin, and their close friend. The group comprises Bela Salazar, Eloise Wong, Lucia de la Garza, and Mila de la Garza.  In May 2021, the Los Angeles Public Library posted a video of the band playing "Racist, Sexist Boy" at a "TEENtastic Tuesdays" event. The song was about an experience Mila, the band''s drummer, had when a schoolmate made a racist comment before the COVID-19 pandemic.', '179841', '1803300', 'https://www.last.fm/music/The+Linda+Lindas');
