INSERT OR IGNORE INTO "artist_enrichment" VALUES('Regressive Left', 'baf5a409-b16c-4ac5-9f70-ba28ac148ff4', NULL, 2020, '[]', '[]', NULL, NULL, '2026-05-23 23:58:24', 3, 'Regressive Left', '["post-punk", "Crank wave", "post-brexit new wave", "indie rock", "dance-punk"]', 'LCD Soundsystem for zoomers: London''s Regressive Left channel political rage into dancepunk hits that''ll keep you moving all night. Recommended for aimless 20-somethings unsure of what to do with their business degree.', '3544', '20626', 'https://www.last.fm/music/Regressive+Left');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('J.D. Blackfoot', '9da6390c-19bb-4bab-a2a9-9b49862345e3', 'US', 1944, '[]', '["psychedelic rock", "psychedelic folk"]', NULL, NULL, '2026-05-23 23:58:24', 1, 'J.D. Blackfoot', '["Garage Rock", "Psychedelic Rock", "blues", "psychedelic", "spotify"]', 'J.D. Blackfoot is not the Indian of the group. He was born in Cleveland in 1944, spent much of the ''60s learning to play the guitar and, as far as heavy-psych record collectors are concerned, struck gold with his first solo record, "The Ultimate Prophecy", in 1970. It wasn''t until a few years later, when he claims to have had a vision of the Battle of Little Big Horn and began writing about Native American stories and causes, that his stage name seemed truly appropriate.', '2788', '16711', 'https://www.last.fm/music/J.D.+Blackfoot');
