INSERT OR IGNORE INTO "artist_enrichment" VALUES('Trashmen', '1f190f39-89cc-426f-ac40-56c31ebf306f', 'US', 1962, '[]', '["garage rock", "rock and roll", "surf rock", "frat rock"]', NULL, NULL, '2026-05-23 23:58:27', 2, 'The Trashmen', '[]', NULL, '12451', '84352', 'https://www.last.fm/music/+noredirect/Trashmen');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Eteraz', '98d5282d-8bb7-42d8-a1e8-9a2a953c23a4', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:58:27', 2, 'Eteraz', '["hardcore", "punk", "d-beat", "hardcore punk", "olympia"]', '"EVIL IN THE EYES OF WHOM?   With your borders, your walls and towers, your armies in every street, your methods of keeping us divided, broken, and imprisoned - we are the evil ones? We are condemned when we choose to fight back; when we reject gender, sexual, and social norms; when we have dark skin; when we reject your ideologies; when we subvert your systems of power and domination.   So we claim this mark you have put upon us, we claim EVIL as a symbol of power and defiance.', '1114', '12937', 'https://www.last.fm/music/eteraz');
