INSERT OR IGNORE INTO "artist_enrichment" VALUES('Sinn Sisamouth & Ros Sereysothea', '96be6ed7-2a30-4be8-ae8c-d219c806c7f9', 'KH', 1932, '[]', '["singer-songwriter", "cambodian"]', NULL, NULL, '2026-05-23 23:58:34', 3, 'ស៊ីន ស៊ីសាមុត', '["soul", "pop", "garage", "cambodia"]', 'Sinn Sisamouth (Khmer: ស៊ីន ស៊ីសាមុត) and Ros Serey Sothea (Khmer: រស់ សេរីសុទ្ធា) were the two most popular singers in the golden age of Cambodian pop.', '512', '5638', 'https://www.last.fm/music/Sinn+Sisamouth+&+Ros+Sereysothea');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Grandmaster Flash & The Furious Five', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:58:34', 2, 'Grandmaster Flash & The Furious Five', '[]', 'Joseph Saddler (born January 1, 1958 in Bridgetown, Barbados) better known as Grandmaster Flash, is an American hip hop musician and DJ; one of the pioneers of hip-hop DJing, cutting, and mixing. Grandmaster Flash and the Furious Five were inducted into the Rock and Roll Hall of Fame in 2007, becoming the first hip hop/rap artists to be so honored.  Saddler''s family migrated to the United States from the West Indies, and he grew up in the Bronx. He currently lives in the Morrisania section of the South Bronx.', '311244', '1701926', 'https://www.last.fm/music/+noredirect/Grandmaster+Flash+&+The+Furious+Five');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('LL Cool J', 'a4dd0e77-83b8-4e92-89b7-effb0e47fd8c', 'US', 1968, '[]', '["hardcore hip hop", "east coast hip hop", "rock and indie", "boom bap", "hip hop", "pop rap", "rap"]', NULL, NULL, '2026-05-23 23:58:35', 1, 'LL Cool J', '["Hip-Hop", "rap", "hip hop", "80s", "rnb"]', 'James Todd Smith (born January 14, 1968 in Bay Shore, New York), better known as LL Cool J (Ladies Love Cool James),  is a Grammy Award winning American rapper and actor signed to Def Jam. He has released twelve studio albums over his 27 year career, has starred in numerous feature films and currently plays Agent Sam Hanna on the hit show NCIS: Los Angeles.  Born in Bay Shore, New York, and raised between St. Albans, New York and Hollis, New York in the borough of Queens.', '1220431', '12216628', 'https://www.last.fm/music/LL+Cool+J');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('French Vanilla', '8b647c17-ca0c-4ff6-b2a7-ba63f9e4a88d', 'US', 2013, '["post-punk"]', '["post-punk"]', NULL, NULL, '2026-05-23 23:58:35', 10, 'French Vanilla', '["post-punk", "indie rock", "art punk", "los angeles", "California"]', 'Taking inspiration from jagged post-punk and subversive performing arts, Los Angeles band French Vanilla brought energy and guile to their saxophone-heavy art punk. The band grew more into their sound through frequent touring, and explored deep themes both personal and political on their 2018 sophomore album How Am I Not Myself?  French Vanilla were formed in the Los Angeles area in 2013 by singer Sally Spitz, guitarist/bassist Ali Day, drummer Greg Shilton, and bassist/saxophonist Daniel Trautfield.', '27277', '214267', 'https://www.last.fm/music/French+Vanilla');
