INSERT OR IGNORE INTO "artist_enrichment" VALUES('Doxa Sinistra', 'f67b1072-e0e9-45f1-a442-0f699e4a9e21', 'NL', 1980, '[]', '["idm", "experimental", "minimal synth", "industrial", "dutch"]', NULL, NULL, '2026-05-23 23:58:52', 1, 'Doxa Sinistra', '["industrial", "minimal synth", "experimental", "electronic", "minimal wave"]', 'Doxa Sinistra was a Dutch duo consisting of Hanjo Erkamp and Brian Dommisse, who made experimental electronic music in the 1980''s.', '3982', '49712', 'https://www.last.fm/music/Doxa+sinistra');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('100%', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:58:52', 1, '100%', '["k-pop", "eurodance", "Korean", "electronic", "pop"]', 'There are several artists using this name: 1) 100% is artist Benji Santos, they also released music under the name Whatever, Dad and Aro.  2) 100% is an Eurodance project from Germany. It was created and produced by Ramin Naghachian, and Rachid Nouri. 100% released the single "Power Of Light" in 1994 featuring Melanie Thornton and Michael Romeo.  3) 100% is also an alternative rock / punk band from Czech Republic. They started in London, UK in 1996 with four members', '143444', '1838977', 'https://www.last.fm/music/100%25');
