INSERT OR IGNORE INTO "artist_enrichment" VALUES('Partner Look', '641a2bda-0ef3-47f4-a430-0c81edd0250a', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:21', 7, 'Partner Look', '["indie pop", "indie rock", "yandex music", "upcoming album 2022", "female vocalists"]', 'Partners, Sisters and Friends. Partner Look are a Melbourne-based band made up of German sisters Ambrin (Cool Sounds) and Anila Hasnain (Studio Magic), who are joined by their partners Dainis Lacey (Cool Sounds) and Lachlan Denton (The Ocean Party).', '4933', '24738', 'https://www.last.fm/music/Partner+Look');
