INSERT OR IGNORE INTO "artist_enrichment" VALUES('Pódium', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:10', 1, 'Pódium', '["spanish", "punk", "valencia", "spain", "female fronted band"]', 'Slovenly Recordings presents the debut LP from Pódium de València. Conceived by Nick Trampolino, armed with a drum machine and a guitar, this project quickly evolved into a five-piece platoon. Pulsating with the epic aggression of hardcore, the impersonal and perverse tone of industrial metal, and fully balanced with the liveliness of the authentic surf scene, they are a curious mixture of Ministry (circa 1989), Man or Astro-man? and the goddamn Go-Go’s ablaze with the pyromaniacal tendencies of Steve Albini’s Shellac.', '745', '7546', 'https://www.last.fm/music/P%C3%B3dium');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Richard Rose', '343bbc46-b6f3-4583-9c50-d8e2e2676523', NULL, NULL, '[]', '[]', 'Richard Rose may refer to:', 'https://en.wikipedia.org/wiki/Richard_Rose', '2026-05-23 23:59:23', 15, 'Richard Rose', '[]', 'Richard Rose is a brand new four piece band fronted by Chris Shaw (Ex-Cult, GØGGS) and Orville Neeley of the OBN IIIs. On their epnymous début EP, released in 2019 on In The Red Records, are four Stoogey, heavy jams that are simply face-melting and stretch out more than anything from their previous bands.', '1894', '9022', 'https://www.last.fm/music/Richard+Rose');
