INSERT OR IGNORE INTO "artist_enrichment" VALUES('Paul Roessler', 'c74f1565-3f45-4a35-b9ee-076539e10aab', 'US', 1958, '[]', '[]', NULL, NULL, '2026-05-23 23:59:24', 1, 'Paul Roessler', '[]', 'Paul Roessler was a prominent member of the L.A. punk scene during the late 1970s and ''80s. He played keyboards in bands such as The Screamers, Twisted Roots, 45 Grave, Nervous Gender, SAUPG, Geza X and the Mommymen, Mike Watt and the Secondmen, Nina Hagen and The Deadbeats. Paul has also put out solo recordings such as "Abominable" and "Curator" and a rock opera entitled "Burnt Church" with Jeff Parker.', '149', '1064', 'https://www.last.fm/music/Paul+Roessler');
