INSERT OR IGNORE INTO "artist_enrichment" VALUES('The UV Race', '423dfc86-5f14-4c92-bd7a-72fa264a2164', 'AU', 2007, '[]', '[]', NULL, NULL, '2026-05-23 23:58:07', 4, 'The UV Race', '["Garage Punk", "Garage Rock", "australian", "punk", "post-punk"]', 'The UV Race is a fantastic group of mongoloids from Melbourne, Australia that play memorable punk music. Boasting members of Eddy Current Suppression Ring and Straightjacket Nation', '3830', '87053', 'https://www.last.fm/music/The+Uv+Race');
