INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Frowning Clouds', 'c7cb2a33-dd42-4ca6-833b-4588c3585a48', 'AU', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:28', 1, 'The Frowning Clouds', '["Garage Rock", "australian", "Retro", "garage", "60s feel"]', 'Imagine a 60s teenage Garage band who are in love with the Brian Jones era of the Rolling stones, and they are interested in a touch of psych and punk. From Geelong, Australia.  http://www.myspace.com/thefrowningclouds http://www.triplejunearthed.com/TheFrowningClouds http://thefrowningclouds.bandcamp.com/', '36946', '309664', 'https://www.last.fm/music/The+Frowning+Clouds');
