INSERT OR IGNORE INTO "artist_enrichment" VALUES('Anon', 'd0438ad9-07d7-40aa-8a31-32e8e6a85584', 'GB', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:36', 2, 'Anon', '["happy hardcore", "electronic", "hardcore", "black metal", "uk Hardcore"]', 'There appears to be more than one artist with this name.  1. "Anon" is a short form of "anonymous."  This can be used as an "artist name" for any piece of music where the composer or performer is historically unknown, but whose music survives.  If the artist is unknown only to you, don''t use "Anon" or " Anonymous".  Fix your tags instead.  2.', '34213', '212515', 'https://www.last.fm/music/Anon');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Nicfit', '9df3d5db-e1af-40c4-bea2-f45ca7e2c98b', 'JP', NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:37', 12, 'Nicfit', '["no wave", "post-punk", "punk", "punk rock", "Garage Punk"]', '1). NicFit is a no wave band from Nagoya, Japan.  https://nicfitnag.bandcamp.com/  2). Nicfit is a noise rock band from Bandung, Indonesia.  https://soundcloud.com/nicfitnoiserock', '1211', '13098', 'https://www.last.fm/music/nicfit');
