INSERT OR IGNORE INTO "artist_enrichment" VALUES('Chiefs', '90218af4-4d58-4821-8d41-2ee295ebbe21', 'GB', 2003, '[]', '["rock", "synthpop", "alternative rock", "british", "uk", "indie rock", "power pop", "indie", "alternative", "synth-pop", "britpop", "dance-pop", "post-punk revival", "pop rock", "english", "rock and indie"]', NULL, NULL, '2026-05-23 23:59:42', 2, 'Kaiser Chiefs', '["Stoner Rock", "desert rock", "heavy", "rock", "riffing"]', 'Beat maker and Melbourne, Australia resident, one to watch for 2013.', '14268', '71683', 'https://www.last.fm/music/Chiefs');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Kiss Offs', '338758d9-915f-4df8-a37d-6f10cdd19602', 'US', 1997, '[]', '[]', NULL, NULL, '2026-05-23 23:59:42', 2, 'The Kiss Offs', '["under 2000 listeners", "austin", "unknowns", "Austin TX", "lo-fi unknowns"]', 'Since their Austin, TX, debut in 1997, the Kiss-Offs have brought on their hectic, noisy garage punk comparable to the likes of the Grifters, Emily''s Sassy Lime, and Bratmobile. Accompanied by a tongue in cheek stage show that included the use of strobe lights and pyrotechnics, Dwayne Barnes (drums/ vocals), Gavin Scott (bass/ vocals), Katey Jones (keyboard/ vocals), Travis Higdon (guitar/ vocals), and Phillip Niemeyer (guitar/ vocals) released their first EP, Love Evidence, through Peek-A-Boo Records in 1997.', '593', '7480', 'https://www.last.fm/music/The+Kiss+Offs');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Viscounts', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:43', 1, 'The Viscounts', '["Rock and Roll", "jazz", "60s", "rock n roll", "night"]', 'Their are two bands  The Viscounts, both performing half sixties. One of them British (Mercybeat) and one of them American (Surf) 1: The Viscounts were a British pop group from London. Its members had formerly been part of a TV ensemble called Morton Fraser''s Harmonica Gang. They quit the group and formed The Viscounts in Late April 1958, playing local shows and eventually attracting the attention of manager Larry Parnes. He got them billed to better venues and signed them to Pye Records in 1960.', '27602', '106941', 'https://www.last.fm/music/The+Viscounts');
