INSERT OR IGNORE INTO "artist_enrichment" VALUES('Johnny Angel', '0d872b9b-65b1-4beb-9b1c-f1f987293ed8', NULL, NULL, '[]', '[]', 'Johnny Angel is a 1945 American film noir directed by Edwin L. Marin and written by Steve Fisher (adapted by Frank Gruber) from the 1944 novel Mr. Angel Comes Aboard by Charles Gordon Booth.  The movie stars George Raft, Claire Trevor and Signe Hasso, and features Hoagy Carmichael.', 'https://en.wikipedia.org/wiki/Johnny_Angel', '2026-05-23 23:59:48', 1, 'Johnny Angel', '["screamo", "hardcore", "oldies", "rock n roll", "emo"]', NULL, '2273', '11706', 'https://www.last.fm/music/Johnny+Angel');
