INSERT OR IGNORE INTO "artist_enrichment" VALUES('Sir Gibbs', 'abb67dc3-5d23-47a4-a1ac-a933b2aa0f57', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:57', 1, 'Sir Gibbs', '["early reggae"]', 'Sir Gibbs is a pseudonym used by Jamaican reggae producer Joe Gibbs. An example of a record released by Gibbs under the Sir Gibbs moniker is People Grudgeful (1968).', '460', '1616', 'https://www.last.fm/music/Sir+Gibbs');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Pixies', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:58', 1, 'Pixies', '["alternative rock", "alternative", "indie", "indie rock", "rock"]', 'Pixies is an American alternative rock band formed in Boston, Massachusetts, in 1986. The original lineup consisted of Black Francis (vocals, rhythm guitar), Joey Santiago (lead guitar), Kim Deal (bass, vocals), and David Lovering (drums). Pixies are associated with the alternative rock movement of the late 1980s and early 1990s and incorporate elements of punk rock and surf rock. Their music is characterised by dynamic loud-quiet-loud shifts and unconventional song structures.', '4302782', '217338644', 'https://www.last.fm/music/Pixies');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Kaput', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:58', 1, 'Kaput', '["rap", "hip hop", "glitch", "art rock", "no wave"]', 'Kaput is a Chicago based Post Punk/Art Rock/No Wave project by Nadia Garofalo (Heavy Feelings , formerly of Ganser), producer and engineer Brian Fox (Electrical Audio), and M. Sord (Jon Spencer and the Hitmakers).', '2092', '14654', 'https://www.last.fm/music/Kaput');
