INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ilhan Mimaroglu', '28492947-7415-4f4b-91a1-303361d39690', 'TR', 1926, '[]', '["turkish"]', NULL, NULL, '2026-05-23 23:59:59', 8, 'İlhan Mimaroğlu', '["electronic", "turkish", "contemporary classical", "composer", "Contemporary"]', 'İlhan Mimaroğlu (March 11, 1926 – July 17, 2012) was a musician and electronic music composer. He was born in Istanbul, Turkey, the son of the famous architect Mimar Kemaleddin Bey depicted on the Turkish lira banknotes, denomination 20 lira, of the 2009 E-9 emission. He graduated from Galatasaray High School in 1945 and the Ankara Law School in 1949. He went to study in New York supported by a Rockefeller Scholarship. He studied musicology at Columbia University under Paul Henry Lang and composition under Douglas Moore.', '3199', '24418', 'https://www.last.fm/music/Ilhan+Mimaroglu');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Konono Nº1', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-23 23:59:59', 1, 'Konono Nº1', '["afrobeat", "african", "congo", "world", "africa"]', 'Konono Nº1 is a musical group from Kinshasa, Democratic Republic of the Congo (formerly known as Zaire). They combine three electric likembé (a traditional lamellaphone similar to the mbira) with voices, dancers, and percussion instruments that are made out of items salvaged from a junkyard. The group''s amplification equipment is equally rudimentary, including a microphone carved out of wood fitted with a magnet from an automobile alternator.', '20215', '142405', 'https://www.last.fm/music/Konono+N%C2%BA1');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The MC5', '08b736bb-1c82-40b4-8b0b-49e2182a067a', 'US', 1964, '[]', '["rock", "hard rock", "usa", "garage punk", "classic rock", "garage rock", "michigan", "rock and indie", "proto-punk", "lincoln park", "rock & roll"]', NULL, NULL, '2026-05-23 17:26:46', 15, 'MC5', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Isaac Hayes', 'a2361c7d-ddb6-41c1-a9a0-be09fbbb8d21', 'US', 1942, '[]', '["american", "funk", "soul", "disco", "rnb", "film score", "scientology", "film soundtrack", "rock and indie", "smooth soul", "death by stroke"]', NULL, NULL, '2026-05-24 00:00:00', 5, 'Isaac Hayes', '["soul", "funk", "rhythm and blues", "Soundtrack", "rnb"]', 'Isaac Lee Hayes (August 20, 1942 – August 10, 2008) was a trailblazing soul singer, songwriter, composer, musician, producer, and actor whose groundbreaking contributions left an indelible mark on music and culture. Born in Covington, Tennessee, Hayes was raised by his grandparents in Memphis after the loss of his parents. From an early age, he showcased musical talent, singing in church choirs and mastering instruments such as the piano and saxophone.', '987068', '8986530', 'https://www.last.fm/music/Isaac+Hayes');
