INSERT OR IGNORE INTO "artist_enrichment" VALUES('Dark City Sisters', '0a081f60-149c-4b67-8345-dbd57163f6b5', 'ZA', 1958, '[]', '[]', 'The Dark City Sisters were a South African female vocal group formed in 1958 by music producer Rupert Bopape. They recorded several hit records during the 1960s, helping usher in the mbaqanga style of South African music later brought to global prominence by the Mahotella Queens.', 'https://en.wikipedia.org/wiki/Dark_City_Sisters', '2026-05-24 00:00:07', 1, 'Dark City Sisters', '["south africa", "folk", "mbaqanga", "african", "the vitamin b12"]', 'The Dark City Sisters were a South African female vocal group who formed in 1958 and recorded several hits in the 1960s before dissolving in 1971. Their innovative five-part harmonies helped to develop the "mbaqanga" style of music.', '2172', '12931', 'https://www.last.fm/music/Dark+City+Sisters');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('J Mascis & The Fog', 'fa39a9d8-378d-43ed-981e-db5901a5665b', 'US', 2000, '[]', '["indie rock"]', 'J Mascis + The Fog was an American rock band formed by J Mascis in 2000, following the break-up of Dinosaur Jr. The project released two albums; 2000''s More Light and 2002''s Free So Free.', 'https://en.wikipedia.org/wiki/J_Mascis_+_The_Fog', '2026-05-23 17:27:21', 2, 'J Mascis + The Fog', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Donny Benet', 'b5902d08-cc36-4748-bc78-d2090cc7ec9a', NULL, 1981, '[]', '["disco"]', 'Donny Benét (born Benjamin Waples) is an Australian recording artist, based in Sydney. In 2011, he released his debut studio album Don''t Hold Back through indie label Rice is Nice. His fifth studio album, Mr Experience, reached #26 on the ARIA Charts in May 2020.', 'https://en.wikipedia.org/wiki/Donny_Benét', '2026-05-23 17:27:27', 7, 'Donny Benét', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Caetano Veloso', 'f07dbc2f-317b-470f-bad4-5f1b0eb6faf1', 'BR', 1942, '[]', '["experimental", "world", "mpb", "folk", "folk pop", "bolero", "latin", "latin ballad", "acoustic", "ballad", "rumba", "tango", "art pop", "alternative rock", "brazilian", "pop", "tropic\u00e1lia", "brazil", "singer/songwriter", "singer-songwriter", "bossa nova", "contemporary folk"]', NULL, NULL, '2026-05-24 00:00:08', 4, 'Caetano Veloso', '["mpb", "Bossa Nova", "tropicalia", "brazilian", "brasil"]', 'Caetano Emanoel Viana Teles Veloso (born August 7, 1942 in Santo Amaro, Bahia, Brazil), professionally known as Caetano Veloso, is a singer, composer, musician, producer, arranger, writer and political activist, being one of the most popular and influential Brazilian MPB artists of all time. With a career that exceeds five decades, Caetano has built a musical work marked by renewal and widely considered to possess great intellectual and poetic value.', '1116595', '49418642', 'https://www.last.fm/music/Caetano+Veloso');
