INSERT OR IGNORE INTO "artist_enrichment" VALUES('Tenor Saw', '63a2d69c-1d6c-4a28-b61e-3879906c9b84', 'JM', 1966, '[]', '["reggae", "hip hop rnb and dance hall"]', NULL, NULL, '2026-05-24 00:00:12', 2, 'Tenor Saw', '["reggae", "dancehall", "roots reggae", "jamaica", "rub-a-dub"]', 'Clive "Tenor Saw" Bright was raised in the Payne Avenue district of West Kingston. His first single, "Roll Call" was recorded in 1984 for George Phang''s Powerhouse label, on the "Queen Majesty" rhythm. He moved on, with his friend Nitty Gritty, to work with Sugar Minott''s Youth Promotion sound system and label, having hits in Jamaica with "Lots of Sign", "Pumpkin Belly", "Run Come Call Me", and "Fever". His most successful single, however, was "Ring the Alarm", voiced over the "Stalag" rhythm for Winston Riley''s Techniques label.', '128444', '693666', 'https://www.last.fm/music/Tenor+Saw');
