INSERT OR IGNORE INTO "artist_enrichment" VALUES('Miles Davis & John Coltrane', '561d854a-6a28-4aa7-8c99-323e6ce46c2a', 'US', 1926, '[]', '["rock", "classical", "jazz", "american", "funk", "fusion", "trumpet", "jazz rock", "jazz fusion", "post-bop", "hard bop", "modal jazz", "bebop", "jazz-funk", "cool jazz", "jazz-rock", "musical", "trumpeter", "composers", "jazz and blues", "miles davis", "george gershwin", "acting", "instrumental jazz", "jazz musicians", "third stream", "composition", "death by stroke", "death by pneumonia", "midnight", "modal music", "the best of", "3356571013121", "had feet", "trumpeters"]', 'Miles Dewey Davis III (May 26, 1926 – September 28, 1991) was an American trumpeter, bandleader and composer. He is among the most influential and acclaimed figures in the history of jazz and 20th-century music. In a career spanning nearly five decades, Davis was at the forefront of several major stylistic developments in jazz, including bebop, cool jazz, hard bop, third stream, modal jazz, avant-garde jazz, and jazz fusion. His legacy extends into rock, funk, classical, and hip-hop.', 'https://en.wikipedia.org/wiki/Miles_Davis', '2026-05-23 17:30:57', 1, 'Miles Davis', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Bertie Marshall', '2c6b14c1-e2ab-454a-a9ee-41ad64221cbc', 'GB', 1960, '[]', '[]', 'Bertram Lloyd Marshall ORTT (6 February 1936 – 17 October 2012), known as Bertie Marshall, was a pioneer, musician and music instrument maker of the steelpan.', 'https://en.wikipedia.org/wiki/Bertie_Marshall', '2026-05-24 00:00:33', 3, 'Bertie Marshall', '["USA"]', NULL, '397', '1200', 'https://www.last.fm/music/Bertie+Marshall');
