INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Intelligence', '11ab49a5-fd58-4905-997d-57e70064e893', 'US', 1999, '[]', '["garage punk", "garage rock"]', 'The Intelligence is an American rock band from Seattle, formed in 1999. Founded by multi-instrumentalist Lars Finberg (A Frames, Thee Oh Sees), the band currently consists of Finberg, alongside Dave Hernandez (guitar), Drew Church (bass) and Kaanan Tupper (drums).', 'https://en.wikipedia.org/wiki/The_Intelligence', '2026-05-24 00:00:35', 2, 'The Intelligence', '["post-punk", "Lo-Fi", "noise rock", "experimental", "noise"]', 'The Intelligence is a lo-fi indie post punk rock band from Seattle, founded by Lars Finberg, drummer of the A-Frames.  Finberg played since the late ''90s in other bands with vocalist/guitarist Erin Sullivan, and bassist Min Yee: the Dipers, and the Un-Natural Helpers. A Frames and the Intelligence started in 1999. Both acts released singles on Dragnet Records, the indie label Finberg runs with A Frames members Erin Sullivan and Min Yee.  2000, Dragnet released the first A-Frames single, recorded by Chris Woodhouse.', '48967', '840635', 'https://www.last.fm/music/The+Intelligence');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Lazy Eyes', '48b0b244-a822-4f79-9bde-14a88217fe57', 'AU', 2015, '[]', '[]', 'The Lazy Eyes are an Australian psychedelic rock band made up of Harvey "Karate" Geraghty (vocals, guitar, keyboard), Leon Karagic (bass guitar), Noah Martin (drums) and Itay "Sasha" Shachar (vocals, guitar). Their debut album, SongBook, appeared in 2022. The Lazy Eyes have headlined shows in Australia, United States and United Kingdom.', 'https://en.wikipedia.org/wiki/The_Lazy_Eyes', '2026-05-23 17:31:25', 1, 'The Lazy Eyes', NULL, NULL, NULL, NULL, NULL);
