INSERT OR IGNORE INTO "artist_enrichment" VALUES('Art Object', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:00:50', 1, 'Art Object', '["punk", "new wave", "Post punk", "punk rock", "art punk"]', 'Art Object were an Art-Punk band from Seattle who released a 45 "Ride The Metro" on Constant Motion Records in 1980.', '427', '2520', 'https://www.last.fm/music/Art+Object');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Pete Zear', 'af18a9bc-e4ab-4068-9489-b64e8186fcf1', 'US', 1919, '[]', '["folk", "singer-songwriter", "contemporary folk"]', 'Peter Seeger (May 3, 1919 – January 27, 2014) was an American singer, songwriter, musician, and left-wing social activist. He was a fixture on nationwide radio in the 1940s and had a string of hit records in the early 1950s as a member of The Weavers, especially their recording of Lead Belly''s "Goodnight, Irene", which topped the charts for 13 weeks in 1950. Members of the Weavers were blacklisted during the McCarthy Era. In the 1960s, Seeger re-emerged on the public scene as a prominent singer ', 'https://en.wikipedia.org/wiki/Pete_Seeger', '2026-05-23 17:34:22', 1, 'Pete Seeger', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Laurel Aitken', 'aef5b6b3-c1f3-4dbb-9755-50842da36a63', 'JM', 1927, '[]', '["ska", "reggae", "rocksteady", "calypso", "singers", "reggae music", "mentos"]', 'Lorenzo "Laurel" Aitken (22 April 1927 – 17 July 2005) was a Cuban-Jamaican singer and one of the pioneers of ska music. He is often referred to as the "Godfather of Ska".', 'https://en.wikipedia.org/wiki/Laurel_Aitken', '2026-05-24 00:00:51', 3, 'Laurel Aitken', '["ska", "reggae", "rocksteady", "skinhead reggae", "jamaica"]', 'Lorenzo Aitken (22 April 1927 – 17 July 2005), better known by the stage name Laurel Aitken, was an influential Caribbean singer and one of the pioneers of Jamaican ska music. He is often referred to as the "Godfather of Ska".  Born in Cuba of mixed Cuban and Jamaican descent, Aitken and his family settled in Jamaica in 1938. After an early career working for the Jamaican Tourist Board singing mento songs for visitors arriving at Kingston Harbour, he became a popular nightclub entertainer.', '138913', '1497347', 'https://www.last.fm/music/Laurel+Aitken');
