INSERT OR IGNORE INTO "artist_enrichment" VALUES('Voight-Kampff', '1af2fb37-ee5f-4268-b4f2-64ad14d5fb38', 'FR', 2010, '[]', '["thrash metal", "metal"]', 'Blade Runner is a 1982 science fiction film directed by Ridley Scott from a screenplay by Hampton Fancher and David Peoples. Starring Harrison Ford, Rutger Hauer, Sean Young, and Edward James Olmos, it is an adaptation of Philip K. Dick''s 1968 novel Do Androids Dream of Electric Sheep? The film is set in a dystopian future Los Angeles of 2019, in which synthetic humans known as replicants are bio-engineered by the powerful Tyrell Corporation to work on space colonies. When a fugitive group of ad', 'https://en.wikipedia.org/wiki/Voight_Kampff', '2026-05-23 17:47:21', 3, 'Voight Kampff', NULL, NULL, NULL, NULL, NULL);
