INSERT OR IGNORE INTO "artist_enrichment" VALUES('Robert Fripp (w/ Daryl Hall)', '898b645e-eed2-490a-8ce2-0e7a4d2d5bc8', 'GB', 1946, '[]', '["progressive rock", "ambient", "british", "uk", "art rock", "electroacoustic", "drone", "experimental rock", "english", "classic pop and rock", "eclectic prog"]', 'Robert Fripp (born 16 May 1946) is an English musician, composer, record producer, and author, best known as the guitarist, founder and only constant member of the progressive rock band King Crimson. He has worked extensively as a session musician and collaborator, notably with David Bowie, Blondie, Brian Eno, Peter Gabriel, Peter Hammill, Daryl Hall, the Roches, Talking Heads, and David Sylvian. He also composed the startup sound of Windows Vista, in collaboration with Tucker Martine and Steve ', 'https://en.wikipedia.org/wiki/Robert_Fripp', '2026-05-23 17:37:01', 1, 'Robert Fripp', NULL, NULL, NULL, NULL, NULL);
