INSERT OR IGNORE INTO "artist_enrichment" VALUES('Delta 5', 'b05af404-b129-4c9e-9606-01baa53e05f9', 'GB', 1979, '[]', '["punk", "uk", "alternative", "england", "leeds", "classic pop and rock"]', NULL, NULL, '2026-05-24 00:01:23', 1, 'Delta 5', '["post-punk", "new wave", "female vocalists", "80s", "riot grrrl"]', 'Delta 5 was a post-punk band formed in 1979 in Leeds, England. The band consisted of Julz Sale (vocals, guitar), Alan Riggs (guitar), Ros Allen (bass), Bethan Peters (bass) and Kelvin Knight (drums). The band released one album, "See the Whirl", and five singles before disbanding in 1981. The band were noted for their feminist, political lyrics and lineup that included two bass guitarists. A retrospective of their work, "Singles & Sessions 1979–1981", was released in 2006 by Kill Rock Stars.', '179479', '1376077', 'https://www.last.fm/music/Delta+5');
