INSERT OR IGNORE INTO "artist_enrichment" VALUES('Danny Elfman', '5b24fbab-c58f-4c37-a59d-ab232e2d98c4', 'US', 1953, '[]', '["soundtrack", "american", "singer", "game", "video game", "score", "lyricist", "film score", "vgm", "film soundtrack", "film composer", "soundtracks", "modern classical", "united states", "show tunes", "television music", "2008 universal fire victim"]', NULL, NULL, '2026-05-24 00:01:26', 3, 'Danny Elfman', '["Soundtrack", "instrumental", "composer", "Classical", "Soundtracks"]', 'Daniel Robert "Danny" Elfman (born May 29, 1953 in Los Angeles, CA) is an American composer, best known as the lead singer and songwriter for the rock band Oingo Boingo, from 1976 to 1995 and later for scoring music for television and film and creating The Simpsons main title theme as well as the 1989 Batman movie theme. He has scored the majority of the films for his long-time friend Tim Burton.  Born in Los Angeles, he entered the film industry in 1976, initially as an actor.', '1621802', '34359210', 'https://www.last.fm/music/Danny+Elfman');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Experience Unlimited', 'f6ddf3ec-cf9b-45e5-a01d-a48790cecc00', 'US', 1975, '["funk", "go-go"]', '["funk", "go-go"]', 'The European Union (EU) is a political and economic union of 27 member states that are located primarily in Europe. A supranational union with a total area of 4,233,255 km2 (1,634,469 sq mi) and an estimated population of over 450 million as of 2025, its member states generated a nominal gross domestic product (GDP) of around €18.802 trillion in 2025, accounting for approximately one sixth of global economic output. The EU is often described as a sui generis political entity combining characteri', 'https://en.wikipedia.org/wiki/E.U.', '2026-05-23 17:58:53', 4, 'E.U.', NULL, NULL, NULL, NULL, NULL);
