INSERT OR IGNORE INTO "artist_enrichment" VALUES('Haba Haba Group', 'fc0736e5-c023-4de2-bcab-416ae5cd058b', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:01:29', 1, 'Haba Haba Group', '["indonesia", "World Music", "Ritual", "southeast asian", "sublime frequencies"]', 'The Haba Haba Group is from the Tapanuli Selatan Region of North Sumatra, Indonesia. They perform music in the "Haroan boru" style, music for wedding ceremonies.', '2097', '7889', 'https://www.last.fm/music/Haba+Haba+Group');
