INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ty Segall & White Fence', '07a17571-81fc-4cf8-a634-98f0d926d313', 'US', 1987, '[]', '["glam rock", "noise rock", "lo-fi", "garage rock", "psychedelic rock", "garage punk", "rock", "_edit"]', NULL, NULL, '2026-05-24 00:01:33', 7, 'Ty Segall', '["Garage Rock", "Psychedelic Rock", "Lo-Fi", "psychedelic", "garage"]', 'Ty on White! Ty Fence! White Segall! White on Ty! Every position/color in the rainbow/stripe in the flag, no quarter given, no corner unrocked in this glintingly lyrsergic meeting of minds.', '26849', '545060', 'https://www.last.fm/music/Ty+Segall+&+White+Fence');
