INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Slickee Boys', '742f08e7-b976-41f4-9593-3a411de66eaf', 'US', NULL, '[]', '["pop punk", "surf punk", "power pop"]', 'The Slickee Boys were a Washington, D.C.-area punk-psychedelic-garage rock band whose most-remembered lineup consisted of guitarist Marshall Keith, guitarist Kim Kane, singer Mark Noone and drummer Dan Palenski. The group was named after a GI slang term for the rockabilly-inspired Korean street toughs who sold black market goods to American soldiers.', 'https://en.wikipedia.org/wiki/The_Slickee_Boys', '2026-05-23 23:58:26', 1, 'The Slickee Boys', '["Garage Rock", "rock", "Psychedelic Rock", "80s", "80''s"]', 'The Slickee Boys are a Washington, D.C.-area psychedelic / garage rock / punk band, led by Kim Kane, Mark Noone, and Marshall Keith. The band has become underground legends in the D.C. punk community. They were known for their wild costumes and graphics.', '3352', '31829', 'https://www.last.fm/music/The+Slickee+Boys');
