INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Birthday', 'ec4ed3f8-f36b-4042-bc74-04e31f6e150e', 'JP', 2005, '[]', '["japanese", "rock"]', NULL, NULL, '2026-05-24 00:01:41', 1, 'The Birthday', '["Garage Rock", "japanese", "J-rock", "rock", "alternative rock"]', 'The Birthday is a Japanese garage rock band which formed in 2006.  Members: Vocals (since 2025), Bass: Hirai Haruki (ヒライハルキ) (former member of てるる...) Vocals (since 2025), Drums: Kuhara Kazuyuki (クハラカズユキ) (former member of THEE MICHELLE GUN ELEPHANT) Vocals (since 2025), Guitar: Fuji Kenji  (フジイケンジ / 藤井謙二) (former member of THE BARRETT and My Little Lover) Vocals (from 2025): Guest vocalists like Takumi Kitamura of DISH//', '39160', '2311587', 'https://www.last.fm/music/The+Birthday');
