INSERT OR IGNORE INTO "artist_enrichment" VALUES('Gary Warren', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:01:42', 1, 'Gary Warren', '["rockabilly", "Garage Rock", "garage", "Surf", "Horror Surf"]', 'Gary Warren was a young British actor in the 1960s, famous for his teenage role in the much loved 1970 film, ''The Railway Children'' and, particularly, his role as Cedric Collingford in British cult TV series, ''Catweazle''. He also played the title role in another TV series, ''Alexander the Greatest''. The President Records label dragged him into the studio to record a (remarkably decent) single with him, 1971''s ''Lucky Guy'' b/w ''Jennifer Please''.', '2172', '7369', 'https://www.last.fm/music/Gary+Warren');
