INSERT OR IGNORE INTO "artist_enrichment" VALUES('Brian Case', '85e3426a-5348-4bf9-98e1-949495232391', 'US', NULL, '[]', '[]', 'Brian Case (born 14 January 1958) is an English former professional rugby league footballer who played in the 1970s, 1980s and 1990s. He played at representative level for Great Britain and England, and at club level for Warrington, Wigan and Leigh, as a prop.', 'https://en.wikipedia.org/wiki/Brian_Case', '2026-05-24 00:02:14', 9, 'Brian Case', '["USA", "experimental", "chicago", "guitar", "All"]', 'Brian Case is a composer, trombonist and guitarist.', '1103', '11500', 'https://www.last.fm/music/Brian+Case');
