INSERT OR IGNORE INTO "artist_enrichment" VALUES('METZ', '449c400c-8312-4c1d-bed8-c8d774090759', NULL, 2008, '[]', '["rock", "alternative rock", "noise", "punk", "punk rock", "grunge", "canadian", "alternative", "post-hardcore", "noise rock", "toronto"]', NULL, NULL, '2026-05-24 00:02:13', 2, 'METZ', '["noise rock", "alternative", "Canadian", "alternative rock", "indie"]', 'Metz is a noise rock band from Toronto, Canada. The band consists of guitarist Alex Edkins, bassist Chris Slorach and drummer Hayden Menzies.  Formed in 2010, they released their eponymous debut album on the Sub Pop label in 2012.', '215859', '4545115', 'https://www.last.fm/music/METZ');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Naked On The Vague', '22058149-fe2b-469f-8309-bfaeafeef67d', 'AU', 2005, '[]', '["no wave"]', NULL, NULL, '2026-05-24 00:02:15', 3, 'Naked on the Vague', '["no wave", "experimental", "post-punk", "noise rock", "Avant-Garde"]', 'Naked On The Vague (NOTV)  were born out of discontent with the malady of nothingness. This nothing fuels their stabbing assault of doom laden experimental punk.    Originally a keys, guitar and drum machine duo (Lucy Cliche - keys/vox/drum box, Nightmare Hopkins - guitar/electronics), NOTV was born out of Sydney, Australia in 2006, with a found organ, a broken bass guitar, a borrowed drum and some old doom poetry. The band recently expanded to include a ‘proper’ rhythm section, with Nic -bass guitar and Lachie - drums.', '10437', '114319', 'https://www.last.fm/music/Naked+On+The+Vague');
