INSERT OR IGNORE INTO "artist_enrichment" VALUES('Nini Raviolette', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:02:24', 2, 'Nini Raviolette', '["coldwave", "new wave", "french", "cold wave", "france"]', 'Nini Raviolette’s unique EP came out on Celluloid in 1980. Her songwriter is none other than Alain Burosse the man behind landmark cyberpunk tv shows ‘Haute Tension’ & ‘l’oeil du cyclone’.', '9145', '30126', 'https://www.last.fm/music/Nini+Raviolette');
