INSERT OR IGNORE INTO "artist_enrichment" VALUES('Coltrane w/ Eric Dolphy', 'badda5cf-f2c5-4dc2-b3d3-07467bdf0f71', 'US', 1928, '[]', '["jazz", "post-bop", "hard bop", "modal jazz", "avant-garde jazz", "free jazz", "jazz and blues", "death by heart attack", "death by diabetes"]', 'Eric Allan Dolphy Jr. (June 20, 1928 – June 29, 1964) was an American jazz multi-instrumentalist, composer, and bandleader. Primarily an alto saxophonist, bass clarinetist, and flautist, Dolphy was one of several multi-instrumentalists to gain prominence during the same era. His use of the bass clarinet helped to establish the unconventional instrument within jazz. Dolphy extended the vocabulary and boundaries of the alto saxophone, and was among the earliest significant jazz flute soloists.', 'https://en.wikipedia.org/wiki/Eric_Dolphy', '2026-05-23 17:42:33', 1, 'Eric Dolphy', NULL, NULL, NULL, NULL, NULL);
