INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Passage', 'fcfacf73-74cf-4480-8305-4d6f5113fe16', 'GB', 1978, '[]', '["minimal wave", "post-punk", "coldwave", "lo-fi", "synth-pop", "synth punk", "art punk", "gothic", "minimal synth", "manchester", "england", "uk"]', NULL, NULL, '2026-05-24 00:02:52', 1, 'The Passage', '["post-punk", "new wave", "experimental", "electronic", "SOLOMUSIKA-post punk"]', 'The Passage were a post-punk band from Manchester, UK who appeared on several record labels including Cherry Red Records and their own label Night & Day.   There is also second artist using this name in Hungary. http://www.passage-hu.eu/  The band was formed as a quartet by songwriter and former Hallé Orchestra percussionist Dick Witts in 1978, but later became a trio. Witts produced the band''s recordings and sung on many of their releases.   Although they never truly broke into the mainstream', '14382', '185669', 'https://www.last.fm/music/The+Passage');
