INSERT OR IGNORE INTO "artist_enrichment" VALUES('Tom Verlaine', 'b54065f0-61b3-4f6f-ba4a-ce15564fbd59', 'US', 1949, '[]', '["rock", "singer-songwriter", "classic pop and rock"]', NULL, NULL, '2026-05-24 00:02:56', 1, 'Tom Verlaine', '["post-punk", "singer-songwriter", "new wave", "rock", "indie"]', 'Tom Verlaine (born Thomas Miller in Morristown, New Jersey, on 13 December 1949; died 28 January 2023) was an American singer, songwriter and guitarist remembered as long-time frontman of Television from 1973 through to 2023.  Verlaine was often considered as one of the most talented performers of the early punk rock era. Verlaine''s poetic lyrics, and his accomplished guitar playing technique were highly influential and widely praised in the music media.', '61707', '756104', 'https://www.last.fm/music/Tom+Verlaine');
