INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jimmy Giuffre', 'a7bd6de6-1739-4927-93f0-693b1f8fed32', 'US', 1921, '[]', '["jazz", "cool jazz", "avant-garde jazz", "free jazz", "jazz and blues", "free improvisation", "death by pneumonia"]', NULL, NULL, '2026-05-24 00:03:02', 1, 'Jimmy Giuffre', '["jazz", "free jazz", "cool jazz", "clarinet", "West Coast Jazz"]', 'James Peter Giuffre (April 26, 1921 – April 24, 2008) was an American jazz composer, arranger and saxophone and clarinet player. He is notable for his development of forms of jazz which allowed for free interplay between the musicians, anticipating forms of free improvisation.  Born in Dallas, Texas, Giuffre (pronounced "Joo-fray") was a graduate of Dallas Technical High School and North Texas State Teachers College (now the University of North Texas).', '59843', '419461', 'https://www.last.fm/music/Jimmy+Giuffre');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Fela Kuti & The Africa ''70', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:03:03', 1, 'Fela Kuti & The Africa ''70', '[]', NULL, '1790', '19142', 'https://www.last.fm/music/+noredirect/Fela+Kuti+&+The+Africa+%2770');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Frankie Rose', '3522e1ec-0b52-47c3-a13e-17ac5db91e9e', 'US', 1979, '[]', '["pop", "noise pop", "rock", "indie", "new wave", "post-punk"]', NULL, NULL, '2026-05-24 00:03:04', 1, 'Frankie Rose', '["dream pop", "indie", "Lo-Fi", "indie pop", "alternative"]', 'As a founding member, songwriter, instrumentalist and vocalist in Vivian Girls and drummer and occasional vocalist in Crystal Stilts, Frankie Rose has been an integral part of two of the most highly acclaimed and influential groups to come out of Brooklyn''s still-vital music scene in the past several years. Her solo project not only reflects the aesthetic earmarks of both those groups, but it also reveals her as a fully-formed artist in her own right.', '220570', '2675605', 'https://www.last.fm/music/Frankie+Rose');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('La Hell Gang', '2b8470ae-70e0-4534-83f7-c0be9852bb29', 'CL', NULL, '["psychedelic rock", "space rock"]', '["psychedelic rock", "space rock"]', NULL, NULL, '2026-05-24 00:03:04', 4, 'La Hell Gang', '["Psychedelic Rock", "chile", "psychedelic", "Stoner Rock", "chilean"]', 'Serious endless hesher jams from this Chilean three-piece!!! The perfect soundtrack to your next bong rip.', '34450', '274320', 'https://www.last.fm/music/La+Hell+Gang');
