INSERT OR IGNORE INTO "artist_enrichment" VALUES('Kate Le Bon', '5dcdb5eb-cb72-4e6e-9e63-b7bace604965', 'US', 1983, '[]', '["rock", "heavy metal", "metal", "american", "band", "hard rock", "usa", "glam rock", "country rock", "classic rock", "soft rock", "acoustic rock", "pop rock", "arena rock", "glam metal", "heartland rock", "aor", "pop and chart", "hair band", "bon jovi", "mainstream rock", "hard fm", "estados unidos"]', 'Bon Jovi is an American rock band formed in Sayreville, New Jersey in 1983. The band consists of singer Jon Bon Jovi, keyboardist David Bryan, drummer Tico Torres, guitarists John Shanks and Phil X, percussionist Everett Bradley, and bassist Hugh McDonald. Original bassist Alec John Such left the band in 1994, and longtime guitarist and co-songwriter Richie Sambora left in 2013.', 'https://en.wikipedia.org/wiki/Bon_Jovi', '2026-05-23 17:50:00', 1, 'Bon Jovi', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Film Toby', '1c26f82c-b35d-4c8e-a1f4-9c20747495c9', 'US', 1991, '[]', '["electronic", "soundtrack", "classical", "video game", "composer", "rock opera", "video game music", "chiptune", "musical comedy", "16-bit", "undertale", "otacore", "digital fusion", "deltarune", "pixel", "indie game soundtrack", "sequencer & tracker", "video game developer"]', 'Robert F. "Toby" Fox (born October 11, 1991) is an American video game developer and composer. He is best known for developing the role-playing video games Undertale and Deltarune.', 'https://en.wikipedia.org/wiki/Toby_Fox', '2026-05-23 17:50:01', 1, 'Toby Fox', NULL, NULL, NULL, NULL, NULL);
