INSERT OR IGNORE INTO "artist_enrichment" VALUES('Keiji Haino/Jim O''Rourke/Oren Ambarchi', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:03:47', 1, 'Keiji Haino/Jim O''Rourke/Oren Ambarchi', '["experimental", "psychedelic", "electronic"]', 'Free improvisation trio consisting of Keiji Haino, Jim O''Rourke, and Oren Ambarchi. They have released five albums, all via Black Truffle Records, and all recorded live in concert: "TIMA FORMOSA" (2010), "in a flash   everything   comes together   as one   there is no   need   for a subject" (2011), "IMIKUZUSHI" (2012), "now   while it''s still warm   let us pour in   all the mystery" (2013), and "only   wanting to melt   beautifully away   is it a', '665', '4757', 'https://www.last.fm/music/Keiji+Haino%2FJim+O%27Rourke%2FOren+Ambarchi');
