INSERT OR IGNORE INTO "artist_enrichment" VALUES('Mike Patton/Jean-Claude Vannier', '489cf278-99eb-460b-b272-9fe36f41c729', 'FR', 1943, '[]', '["french lyricist", "french composer", "arranger"]', 'Jean-Claude Vannier  (born 1943) is a French musician, composer and arranger. Vannier has composed music, written lyrics, and produced albums for many singers.', 'https://en.wikipedia.org/wiki/Jean-Claude_Vannier', '2026-05-23 17:53:11', 2, 'Jean-Claude Vannier', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ulaan Khol', '1dc6e1ac-af34-4c10-952f-1c145f7768ce', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:02:34', 4, 'Ulaan Khol', '["drone", "psychedelic", "experimental", "noise", "ambient"]', 'A project by guitarist and multi-instrumentalist Steven R. Smith (From the Soft Abuse website:) Throughout his career as a solo artist, and through membership with the celebrated ensembles Thuja and Mirza, Steven R. Smith has had a hand in creating some of the most compelling and singular instrumental psychedelic music of the past ten years. Smith''s latest project, Ulaan Khol, moves beyond the Eastern European-inspired sources and scales employed', '12350', '187872', 'https://www.last.fm/music/Ulaan+Khol');
