INSERT OR IGNORE INTO "artist_enrichment" VALUES('Blind Willie Johnson', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:04:14', 1, 'Blind Willie Johnson', '["blues", "delta blues", "gospel", "folk", "Classic Blues"]', 'Blind Willie Johnson (January 25, 1897 – September 18, 1945) was a gospel blues singer, guitarist and songwriter.   While the lyrics of his songs were usually religious, his music drew from both sacred and blues traditions. It is characterized by his slide guitar accompaniment and tenor voice, and his frequent use of a lower-register ''growl'' or false bass voice.  According to his death certificate, Johnson was born in 1897 near Brenham, Texas. (Earlier, Temple, Texas had been suggested as his birthplace.', '272329', '2283492', 'https://www.last.fm/music/Blind+Willie+Johnson');
