INSERT OR IGNORE INTO "artist_enrichment" VALUES('Kim Salmon and the Surrealists', 'c9f8becd-7ec2-42ec-ada0-a1092735d8d1', 'AU', 1987, '[]', '[]', 'Kim Salmon and the Surrealists are an Australian indie rock band formed by Kim Salmon in 1987 when he was living in Perth between the final two tours by The Scientists. When the Scientists stopped, Salmon continued the Surrealists as his main band while playing in Beasts of Bourbon.', 'https://en.wikipedia.org/wiki/Kim_Salmon_and_the_Surrealists', '2026-05-23 17:54:17', 2, 'Kim Salmon and the Surrealists', NULL, NULL, NULL, NULL, NULL);
