INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ronnie Allen', '9eecfc42-ada1-4db4-96f5-f16bb7544ca8', 'US', NULL, '[]', '[]', 'Ronald Allen (15 January 1929 – 9 June 2001) was an English international football player and manager. He was a professional footballer for 19 years, between 1946 and 1964, making 638 appearances in the Football League and scoring 276 goals. He also won five caps for the England national team. He later became a manager at clubs in England, Spain, Portugal, and Greece. His son, Russell, also played professional football throughout the 1970s.', 'https://en.wikipedia.org/wiki/Ronnie_Allen', '2026-05-24 00:04:25', 1, 'Ronnie Allen', '["rockabilly", "rock", "Rock and Roll", "USA", "oldies"]', NULL, '4994', '15549', 'https://www.last.fm/music/Ronnie+Allen');
