INSERT OR IGNORE INTO "artist_enrichment" VALUES('Dante Gonzales', '9c306413-56b6-4ff6-982a-7e4b87d01340', NULL, 1972, '[]', '["modern classical", "electronic", "canada", "canadien", "producer", "arranger", "producteur", "arrangeur", "canadian", "classic pop and rock", "alternative dance", "jazz"]', 'Jason Charles Beck (born 20 March 1972), professionally known as Chilly Gonzales or just Gonzales, is a Canadian musician, songwriter, and producer. Currently based in London, England, he previously lived for several years in Paris, Berlin, and Cologne. Gonzales'' career spans numerous genres. He is known for his rap albums, his collaborations with singer and musician Feist and rapper Drake, his albums of classical piano compositions (including the Solo Piano trilogy), and for his collaborations ', 'https://en.wikipedia.org/wiki/Chilly_Gonzales', '2026-05-23 17:55:27', 1, 'Chilly Gonzales', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Phloen Phromdaen', 'efedb65c-3851-4802-9526-55d69e103247', 'TH', 1939, '[]', '["luk thung"]', 'Somsuan Promsawang (Thai: สมส่วน พรหมสว่าง) (12 June 1939 – 3 August 2024), professionally known  Phloen Phromdaen (Thai: เพลิน พรหมแดน) was a Thai Luk thung (Thai country song) and speak story singer, and a 2012 winner of National Artist from Thailand award.', 'https://en.wikipedia.org/wiki/เพลิน_พรหมแดน', '2026-05-23 17:55:30', 1, 'เพลิน พรหมแดน', NULL, NULL, NULL, NULL, NULL);
