INSERT OR IGNORE INTO "artist_enrichment" VALUES('Agency', 'a3bf00a4-c6af-4c18-8d8f-3d9d420997b1', 'AU', NULL, '[]', '[]', 'Agency may refer to:', 'https://en.wikipedia.org/wiki/Agency', '2026-05-24 00:04:31', 2, 'Agency', '["australia", "Post punk", "Need to Rate", "rock", "thrash metal"]', 'Agency is the name of more than one artist. 1. agency - independent from Munich with the EP Streetlights (https://www.last.fm/music/Agency/Streetlights) 2. Agency - with the records Agency (https://www.last.fm/music/Agency/Agency) and Revolutions (https://www.last.fm/music/Agency/Revolutions) 3. maybe many more', '4627', '44099', 'https://www.last.fm/music/Agency');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Nivhek', '455d7ca3-629d-498c-93f3-9d428dbfe4e0', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:04:32', 1, 'Nivhek', '["ambient", "experimental", "drone", "dark ambient", "USA"]', 'Nivhek is a musical project by Liz Harris, better known as Grouper.   In February 2019 she released the album After its own death / Walking in a spiral towards the house. The music was created during and after residencies in the Azores, Portugal and Murmansk, Russia. It also includes work Harris made at her home in Astoria, Oregon.', '20339', '162016', 'https://www.last.fm/music/Nivhek');
