INSERT OR IGNORE INTO "artist_enrichment" VALUES('Mikal Cronin', 'c1a217e0-4b3e-46d7-9613-6a14c9e70895', 'US', 1985, '[]', '[]', NULL, NULL, '2026-05-24 00:04:49', 2, 'Mikal Cronin', '["Garage Rock", "Lo-Fi", "indie", "Garage Punk", "indie rock"]', 'Mikal Cronin (born December 26, 1985) is an American musician and songwriter. He has released four solo albums and several singles. Cronin is also a member of the bands Okie Dokie, Epsilons, Party Fowl and Moonhearts, and occasionally plays bass guitar and adds backing vocals in Ty Segall''s live band; he has also released an album and a single in collaboration with Segall.', '174443', '2842146', 'https://www.last.fm/music/Mikal+Cronin');
