INSERT OR IGNORE INTO "artist_enrichment" VALUES('Overkill', '97fa7dd1-4706-4fad-b6ff-e099a37837fc', 'US', 1980, '[]', '["80s", "90s", "thrash metal", "metal", "usa", "speed metal", "groove metal", "80s thrash metal", "00s", "classic metal", "10s", "classic thrash metal", "estados unidos"]', NULL, NULL, '2026-05-24 00:05:14', 1, 'Overkill', '["thrash metal", "speed metal", "heavy metal", "metal", "thrash"]', 'Overkill is an American thrash metal band formed in 1980 in New Jersey. The group has undergone numerous line-up changes, with bassist D. D. Verni and vocalist Bobby “Blitz” Ellsworth remaining the only original members. The band has been associated with the East Coast thrash metal scene alongside groups such as Nuclear Assault and Anthrax, and their musical style has been influenced by punk rock and the new wave of British heavy metal. A recurring visual element in the band’s imagery is their mascot “Chaly”', '382477', '15070960', 'https://www.last.fm/music/Overkill');
