INSERT OR IGNORE INTO "artist_enrichment" VALUES('East Brunswick All Girls Choir', '3b6fdea3-1271-44c6-867b-0221043640c5', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:05:35', 1, 'East Brunswick All Girls Choir', '["alternative rock", "indie rock", "australia", "nickleback ripoff", "under 2000 listeners"]', 'East Brunswick All Girls Choir is made up of a mini golf course curator from Lockwood South, a Pool Shark Ninja who relocated from Yokahama, a gaming pizza cooking nerd from Golden Square and one failed cricketer who once walked the hallowed turf of Maiden Gully.', '2432', '38235', 'https://www.last.fm/music/East+Brunswick+All+Girls+Choir');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Routineers', '16e1e50b-c155-479b-8b74-432c899e1520', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:05:35', 1, 'Routineers', '["Garage Rock"]', 'Routineers are a punk/indie-band from Washington, DC, featuring Amanda MacKaye (vocals), Ryan Nelson (guitar, vocals), Todd McDonald (bass) and Ryan Nesper (drums). Their debut CD came out in 2004 and was a split release between Dischord Records and Amanda MacKayes own label “Sammich”. Members of the band had been active and are currently active in bands such as Discount, The Most Secret Method, Beauty Pill, Soccer Team, and probably many more.', '466', '6499', 'https://www.last.fm/music/Routineers');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Red Aunts', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:05:36', 1, 'Red Aunts', '["riot grrrl", "punk", "punk rock", "female vocals", "alternative"]', 'Female punk rockers the Red Aunts were a rough, raw, raunchy combo that arose during the California punk revival of the ''90s. Both praised and dismissed for their garage-band amateurishness early on, the band crafted a grimy, scuzzy sound inflected with subtle strains of blues, country, and pre-Beatles rock & roll. That sound matched well with their lyrics -- the Red Aunts weren''t really political or explicitly feminist; they just wanted to rock out', '73947', '686353', 'https://www.last.fm/music/Red+Aunts');
