INSERT OR IGNORE INTO "artist_enrichment" VALUES('Moss Lime', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:05:49', 1, 'Moss Lime', '["brujas", "rock", "Canadian", "indie", "alternative"]', 'Moss Lime is a trio from Montreal, Québec. Their debut EP, ''July First'' was released in 2014, followed by their first full-length, ''Zoo Du Quebec'' in 2015.', '1671', '12067', 'https://www.last.fm/music/Moss+Lime');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Bing Selfish', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:05:50', 1, 'Bing Selfish', '["new wave", "experimental", "Avant-Garde"]', 'BING SELFISH  "Pop music for the cynical present -- bright, breezy, sardonic, witty, a work of dazzling luminosity that confirms Phil Ochs''s contention that ''In such an ugly time, the true protest is beauty.''"  "Essential for anyone who thinks that rock, politics and humour can''t occupy the same mental and aesthetic space" - The Wire (UK)  Included in The Wire magazine''s list of "60 singers and songs that broke the mould" (May 2004) for his personal', '665', '5829', 'https://www.last.fm/music/Bing+Selfish');
