INSERT OR IGNORE INTO "artist_enrichment" VALUES('Der Plan', '9b048a76-b812-431e-8540-79a62bda5727', 'DE', 1979, '[]', '["synthpop", "industrial", "german", "post-punk", "neue deutsche welle", "ndw", "minimal synth", "zolo"]', 'Der Plan is a German electronic music group from Düsseldorf, formed in the earlier months of 1979 by Moritz Reichelt (A.K.A. Moritz R®), Kai Horn, and Frank Fenstermacher, originally under the name of Weltaufstandsplan ("World Rebellion Plan").', 'https://en.wikipedia.org/wiki/Der_Plan', '2026-05-24 00:05:58', 1, 'Der Plan', '["NDW", "Neue Deutsche Welle", "german", "experimental", "electronic"]', 'German experimental band from Düsseldorf. Started of with very experimental music, but evolved to more ''accessible'' music when Pyrolator joined the band. They formed their own label Ata Tak and released something like 10 records, the last one dating from 2017.', '43473', '537222', 'https://www.last.fm/music/Der+Plan');
