INSERT OR IGNORE INTO "artist_enrichment" VALUES('Bad Times', '05f97d2e-650e-430f-b238-fa186a7c74c4', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:06:25', 1, 'Bad Times', '["Garage Rock", "Garage Punk", "Lo-Fi", "punk", "All"]', 'Bad Times were a one-off band which also included  Eric Friedl of Oblivians fame and Jay Reatard. The band recorded an album’s worth of material after only one practice session in 1998, releasing a self-titled LP in 2001. After one live performance the band disbanded, the members returning to their respective solo commitments.', '7129', '77312', 'https://www.last.fm/music/Bad+Times');
