INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jean Cohen-Solar', '65314b12-0e08-43fa-ba33-baaa7b874c15', 'CA', 1934, '[]', '["rock", "pop", "folk", "blues", "canadian", "singer-songwriter", "music", "canada", "folk rock", "blues rock", "poetry", "soft rock", "contemporary folk", "composers", "classic pop and rock", "singers", "singer and songwriter", "fiction", "sophisti-pop", "singer/songwriter", "novelists", "poets", "lyricists", "nuno"]', 'Leonard Norman Cohen (September 21, 1934 – November 7, 2016) was a Canadian songwriter, singer, poet, and novelist. Themes commonly explored throughout his work include faith and mortality, isolation and depression, betrayal and redemption, social and political conflict, sexual and romantic love, desire, regret, and loss. He was inducted into the Canadian Music Hall of Fame, the Canadian Songwriters Hall of Fame, and the Rock and Roll Hall of Fame. He was invested as a Companion of the Order of ', 'https://en.wikipedia.org/wiki/Leonard_Cohen', '2026-05-23 18:06:17', 1, 'Leonard Cohen', NULL, NULL, NULL, NULL, NULL);
