INSERT OR IGNORE INTO "artist_enrichment" VALUES('Hala Strana', '2bc8404c-8e48-44ab-a90a-367f0830a492', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:06:51', 1, 'Hala Strana', '["psychedelic folk", "folk", "drone", "experimental", "psychedelic"]', 'Hala Strana  was the name of a recording project of American musician Steven R. Smith begun in 2002 as an outlet which allowed him to explore the traditional music of Eastern Europe more fully than possible with his solo work. By incorporating the melodies, scales, and instrumentation of the village music from areas such as Croatia, Hungary, Romania, the Czech Republic and Poland, and while working with numerous musicians who have contributed to the project (including Glenn Donaldson', '68671', '1087481', 'https://www.last.fm/music/Hala+Strana');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Dean Ween', '526c5b19-e016-49bc-a8c3-5b196a0e47f4', 'US', 1970, '[]', '["hard rock", "alternative rock", "lo-fi", "neo-psychedelia", "experimental rock"]', NULL, NULL, '2026-05-24 00:06:51', 2, 'Dean Ween', '["rock", "guitar", "alternative rock", "punk", "Need to Rate"]', 'Dean Ween (born September 25, 1970) is the stage name of Michael "Mickey" Melchiondo, Jr., American guitarist and half of the alternative rock group Ween.', '4370', '14583', 'https://www.last.fm/music/Dean+Ween');
