INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Great Society Band', '316d01a3-73de-45fb-ad67-b7e770b501c5', 'US', 1965, '[]', '["psychedelic rock", "psychedelic pop"]', 'The Great Society may refer to: ', 'https://en.wikipedia.org/wiki/The_Great_Society', '2026-05-23 18:08:12', 1, 'The Great Society', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('My Bloody Valentine', '8ca01f46-53ac-4af2-8516-55a909c0905e', 'IE', 1983, '[]', '["rock", "alternative rock", "shoegaze", "irish", "british", "post-punk", "shoegazing", "uk", "indie rock", "irlande", "ireland", "irlandais", "indie", "indie pop", "noise pop", "dream pop", "noise rock", "english", "classic pop and rock", "creation records", "the lost generation", "spotify boycott", "vyrzukhisuc-artiest"]', 'My Bloody Valentine may refer to:', 'https://en.wikipedia.org/wiki/My_Bloody_Valentine', '2026-05-24 00:07:07', 1, 'My Bloody Valentine', '["shoegaze", "dream pop", "indie", "alternative", "indie rock"]', 'my bloody valentine formed in 1983 in Dublin, Ireland. The band’s best known lineup is Kevin Shields (vocals, guitar), Bilinda Butcher (vocals, guitar), Debbie Googe (bass) and Colm Ó Cíosóig (drums). Their 1988 album Isn''t Anything is generally regarded as one of the most influential records of the period, acting as an important precursor to the early ''90s "shoegazing" scene. In 1991, the band released their second full length album Loveless, later declared one of the finest albums of the 1990s.', '2054500', '127945924', 'https://www.last.fm/music/my+bloody+valentine');
