INSERT OR IGNORE INTO "artist_enrichment" VALUES('Jim Gillette', '474ea687-097c-4ffa-b201-c8e36f6cbe88', 'US', 1967, '[]', '["glam", "glam metal", "heavy metal", "metal"]', NULL, NULL, '2026-05-24 00:07:11', 1, 'Jim Gillette', '["Glam Metal", "heavy metal", "hair metal", "glam rock", "80s"]', 'Jim Gillette, born James Gillette  - Nov 10th, 1968. is an American heavy metal vocalist. Originally a member of Tuff. he recorded an EP with them, Knock Yourself Out.  He then became the vocalist of the 80s Heavy Metal band Nitro, known for his over-the-top attitude and ear-shatteringly high vocals. He released a solo album, Proud To Be Loud in 1987. He is currently a bodybuilder and was married to metal queen Lita Ford  from 1994 to 2011.', '1191', '29107', 'https://www.last.fm/music/Jim+Gillette');
