INSERT OR IGNORE INTO "artist_enrichment" VALUES('Lower Plenty', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:07:13', 3, 'Lower Plenty', '["rock", "Garage Rock", "acoustic", "indie", "australia"]', 'Named after a Melbourne suburb, Lower Plenty are comprised of some of the city’s most talented musicians. The quartet of Daniel Twomey (percussion), Jensen Tjhung (guitar + vocal), Sarah Heyward (percussion + vocal) and Al Montfort (guitar + vocal) hail from various other bands such as Deaf Wish, Total Control, UV Race and The Focus. A departure from the harsher sounds of their other projects, Lower Plenty create beautifully melancholy, suburban-country music that’s made (and often performed) while sitting around the kitchen table.', '7411', '111201', 'https://www.last.fm/music/Lower+Plenty');
