INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ty Segall Band', 'd0a5d602-5172-46ed-9b4d-bae8fb8c33f9', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:07:25', 3, 'Ty Segall Band', '["Garage Rock", "Lo-Fi", "garage", "rock", "Garage Punk"]', 'Ty Segall Band consists of Ty Segall as well as his tour mates Emily Rose Epstein, Charlie Moothart and Mikal Cronin. The full band sounds is meant to be ''a lot harder and louder.'' Their first and only album under this moniker, Slaughterhouse, was released on June 26th, 2012 through In the Red records.', '123693', '1900752', 'https://www.last.fm/music/Ty+Segall+Band');
