INSERT OR IGNORE INTO "artist_enrichment" VALUES('Wicked Witch', 'fc9cb441-3988-46fc-aaba-83a11d9cdffc', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:07:27', 1, 'Wicked Witch', '["funk", "Disco", "electronic", "Fusion", "experimental"]', '1 Now is not the time to doubt your senses - the Wicked Witch does exist. Born and raised in the musical magical cauldron of Washington D.C., Wicked Witch combines elements from alchemical mentors Parliament Funkadelic, Sun Ra, ESG, Run DMC, James Brown and Jimi Hendrix to cast a crazed spell on the innocent listener. An evil mass of machine-funk with lashings of rhythm and blues and fusion delivered direct from the heart of the Witch, misunderstood psycho-genius weaving his solo web deep within the dark studio walls.', '2282', '22304', 'https://www.last.fm/music/Wicked+Witch');
