INSERT OR IGNORE INTO "artist_enrichment" VALUES('Motorik', '2cf84ba2-0466-4e13-9dbc-736db46d692a', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:07:28', 1, 'Motorik', '[]', 'Motorik is a Seattle, WA post-punk three-piece band. Members are Sio (vox and bass), Adrian (guitar) and Hoagie (drums).  Their debut LP, KLANG!, was released in 2008. It was recorded at Calleye Studios with Gary Mula and at Soundhouse with Jack Endino.   Motorik web site: www.motoriks.com   Myspace: www.myspace.com/motorikmusik Purchase CD: http://cdbaby.com/cd/motorik', '166', '769', 'https://www.last.fm/music/Motorik');
