INSERT OR IGNORE INTO "artist_enrichment" VALUES('Zomes', 'eac54baa-e1dd-4ade-83a5-00c4f6aaa472', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:07:38', 6, 'Zomes', '["drone", "psychedelic", "experimental", "Lo-Fi", "instrumental"]', 'Zomes is a new solo project by Asa Osborne (Lungfish, The Pupils, Tear Jerks).   For Zomes'' self-titled 2008 debut, Asa strung together a number of misshapen lo-fi loops and miniatures across an album that references Vincent Gallo-style rundown melancholy, stargazing kraut rock, and a selection of organ-driven passages that bring to mind a miniaturized Religious Knives. Osborne is at his best on pieces like ''Night Signs'', a beautiful, hiss-coated guitar phrase, repeated in a sombre, ambiguous fashion over a couple of minutes.', '17298', '286186', 'https://www.last.fm/music/Zomes');
