INSERT OR IGNORE INTO "artist_enrichment" VALUES('Exhaustion', '041e662f-2584-460a-b0e7-9079c94ac1ee', NULL, NULL, '[]', '[]', 'Exhaust, exhaustive, or exhaustion may refer to:', 'https://en.wikipedia.org/wiki/Exhaustion', '2026-05-24 00:07:57', 3, 'Exhaustion', '["Crust", "grindcore", "hardcore", "french", "crustcore"]', '1. A crust influenced punk-hardcore band from Caen (France) with members of Amanda Woodward, Karysun, Zombies Are Pissed!, Soar, and Fuaim Catha.  http://www.stateofexhaustion.org/  2. Post-punk from Melbourne, Australia.  http://exhaustion.bandcamp.com/  3. Blackened Grind from the UK featuring ex-Throats members  http://exhaustionmetal.bandcamp.com/', '1236', '12067', 'https://www.last.fm/music/Exhaustion');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Specials', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:07:58', 1, 'The Specials', '["ska", "two-tone", "reggae", "punk", "80s"]', 'The Specials is an English “2 Tone” ska revival band  formed in 1977 in Coventry, Warwickshire. Their music combines a danceable ska beat with punk’s energy, underpinned by an informed political and social stance.   The group was formed by songwriter/keyboardist Jerry Dammers, with Terry Hall (vocals), Lynval Golding (guitar, vocals) and a rhythm section featuring Horace Panter (bass) and John Bradbury (drums; born 16 February 1953, died 28 December 2015).', '1137020', '20113784', 'https://www.last.fm/music/The+Specials');
