INSERT OR IGNORE INTO "artist_enrichment" VALUES('Heatwave', 'ce809639-0e34-40c4-86c9-90a162cb3d46', 'GB', 1975, '[]', '["funk", "soul", "disco", "classic pop and rock"]', NULL, NULL, '2026-05-24 00:07:59', 1, 'Heatwave', '["funk", "Disco", "soul", "rnb", "70s"]', 'There are two artists with this name. 1) Funk/disco band from London, UK. 2) Synthwave artist from Germany.  1) Heatwave was an international funk/disco musical band featuring Americans Johnnie Wilder, Jr. and Keith Wilder (vocals) of Dayton, Ohio, Englishman Rod Temperton (keyboards), Swiss Mario Mantese (bass), Czechoslovakian Ernest "Bilbo" Berger (drums), Jamaican Eric Johns (guitar) and Londoner Roy Carter, (guitar).  They were known for their successful songs "Boogie Nights" and "Always and Forever" (from their 1976 debut album', '425526', '2825756', 'https://www.last.fm/music/Heatwave');
