INSERT OR IGNORE INTO "artist_enrichment" VALUES('Charlie Hilton', 'c9afb530-d46a-4fda-a9f0-dc0f8314ab53', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:08:03', 3, 'Charlie Hilton', '["indie pop", "dream pop", "indie", "psychedelic", "female vocalists"]', 'Charlie Hilton is best known for fronting Blouse — the Portland band whose most recent album was released in 2013 — but she’s striking out as a solo artist with a debut of her very own. It’s called Palana and was produced by Unknown Mortal Orchestra’s Jacob Portrait, save for one track that was done by Woods’ Jarvis Taveniere with background support from none other than Mac DeMarco.', '28535', '188510', 'https://www.last.fm/music/Charlie+Hilton');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Maria Violenza', 'f68bb859-2161-47c4-94aa-7874342dc8c2', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:08:03', 1, 'Maria Violenza', '["Italy", "noise pop"]', 'Maria Violenza is an electro / Arabian / (post) punk solo project by Cristina Cusimano, based in Rome, Italy.', '1186', '10521', 'https://www.last.fm/music/Maria+Violenza');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Second Layer', '60c53b34-ba43-4114-8142-0c8e5afe73ce', 'GB', 1979, '[]', '["post-punk", "uk", "london", "england", "punk"]', 'Second Layer were an English post-punk band formed in 1979 by Adrian Borland (vocals, guitar) and Graham Bailey (keyboards, bass guitar, drum programming), both members of the Sound.', 'https://en.wikipedia.org/wiki/Second_Layer', '2026-05-24 00:08:04', 1, 'Second Layer', '["post-punk", "minimal synth", "new wave", "80s", "noise rock"]', 'Second Layer was an electronic-based outlet for The Sound''s Adrian Borland and Graham Bailey. Borland supplied guitars and vocals while Bailey provided keyboards, bass, and drum programming. The full length album World of Rubber was issued in 1981, after two EPs "Flesh as Property" (1979) and "State of Emergency" (1980). Since the duo was central to The Sound''s sound, their side project retained some of that feel, albeit in a slightly detached fashion that''s to be expected when synths and drum machines replace more human elements.', '12844', '123295', 'https://www.last.fm/music/Second+Layer');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Charles Bogert with Toads', '11b80336-72fd-4748-b657-43bc3c139e01', 'US', 1908, '[]', '[]', 'Charles Mitchill Bogert (June 4, 1908 – April 10, 1992) was an American herpetologist, and curator of herpetology and researcher for the American Museum of Natural History.', 'https://en.wikipedia.org/wiki/Charles_Bogert', '2026-05-23 18:12:20', 1, 'Charles Bogert', NULL, NULL, NULL, NULL, NULL);
