INSERT OR IGNORE INTO "artist_enrichment" VALUES('Weird War', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:08:05', 1, 'Weird War', '["Garage Rock", "Garage Punk", "indie", "rock", "psychedelic"]', 'Weird War is an eclectic independent rock''n''roll band stationed in the United States of America. The current lineup consists of Michelle Mae (bass), Alex Minoff (guitar), Sebastian Thomson (drums) and Ian Svenonius (vocals). Former members include Neil Michael Hagerty (vocals/guitar), Jessica Espeleta (guitar) and Steve McCarty (drums). The group currently releases material through the Drag City record label.', '13373', '184617', 'https://www.last.fm/music/Weird+War');
