INSERT OR IGNORE INTO "artist_enrichment" VALUES('Radio Pyongyang', '5fa54d3e-eb89-41b5-9814-fdd8bca9ced1', NULL, NULL, '[]', '[]', 'Pyongyang (Korean: 평양; Hancha: 平壤) is the capital and largest city of North Korea. According to the 2008 population census, it has a population of 3,255,288. Pyongyang is located on the Taedong River about 109 kilometers (68 miles) upstream from its mouth on the Yellow Sea. Pyongyang is a directly administered city (직할시; 直轄市; chikhalsi) with a status equal to that of the North Korean provinces.', 'https://en.wikipedia.org/wiki/Pyongyang', '2026-05-23 18:14:05', 2, 'Pyongyang', NULL, NULL, NULL, NULL, NULL);
