INSERT OR IGNORE INTO "artist_enrichment" VALUES('Eddie and the Subtitles', 'e7a9cdbd-528b-4aac-90e6-a42c19e86155', 'US', NULL, '[]', '["punk", "usa"]', NULL, NULL, '2026-05-23 23:57:00', 1, 'Eddie and the Subtitles', '["punk", "rockabilly", "deathrock", "punk rock", "horror punk"]', 'Eddie and The Subtitles was a punk band from Orange County, California. Their 1980 LP "Skeletons in the closet" featured "American society", later covered by L7.', '2520', '21463', 'https://www.last.fm/music/Eddie+and+the+Subtitles');
