INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ris Paul Ric', 'ae5b2f52-0ffb-4df8-9b73-0ec99c3a8aa6', 'US', NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:08:10', 2, 'Ris Paul Ric', '["singer-songwriter", "indie", "indie pop", "art pop", "ambient pop"]', 'Ris Paul Ric is a solo project of Chris Richards, formerly of Washington, DC-area post-punk group Q and Not U. In 2005 Richards released his debut album, Purple Blaze, which combined elements of folk, funk, and ambient electronica, and toured in support of the album. Chris Richards collaborated with Tim Hecker on Purple Blaze. As of 2006, Richards is touring and collaborating with Baltimore DJ Dave Nada.  The name "Ris Paul Ric" is based on Richards'' full name, "Christopher Paul Richards".', '5719', '115506', 'https://www.last.fm/music/Ris+Paul+Ric');
