INSERT OR IGNORE INTO "artist_enrichment" VALUES('Crystal Castles', 'b1570544-93ab-4b2b-8398-131735394202', 'CA', 2006, '[]', '["electronic", "synthpop", "pop", "dance", "experimental", "canadian", "canada", "canadien", "electronica", "synth-pop", "electropop", "electropunk", "alternative dance", "indie dance", "electroclash", "bitpop", "new rave", "edm", "rock and indie", "indie electronic", "witch house", "alternative/indie rock", "synth punk", "at home", "proto-hyperpop", "dj tools / acapellas"]', NULL, NULL, '2026-05-24 00:08:26', 2, 'Crystal Castles', '["electronic", "8-bit", "new rave", "electro", "electronica"]', 'Crystal Castles was an experimental /  electronic band which formed in 2003 in Toronto, Ontario, Canada and last consisted of Ethan Kath and vocalist Edith Frances. Alice Glass served as the lead vocalist for the group since its foundation until 2014.  They are named after the lyrics "The fate of the world is safe in Crystal Castles" and "Crystal Castles, the source of all power" both from the theme song for She-Ra''s fortress. They are known for their melancholic lo-fi sound and their explosive live shows.', '3212321', '243250169', 'https://www.last.fm/music/Crystal+Castles');
