INSERT OR IGNORE INTO "artist_enrichment" VALUES('Bark Bark Bark', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:08:29', 1, 'Bark Bark Bark', '["electronic", "dance", "indie pop", "indie rock", "All"]', 'Bark Bark Bark is an experimental, cut and paste electronic punk band based in Los Angeles, California but originally from Tucson, Arizona and formed by Jacob Safari (The Mae Shi). The band consists of Jacob Safari and guest artists and producers. Bark Bark Bark was discovered by Los Angeles based Retard Disco after Jacob played a show at The Smell and gave the label a cassette tape that later turned up to be completely blank. They have so far released one full length album', '4794', '82469', 'https://www.last.fm/music/Bark+Bark+Bark');
