INSERT OR IGNORE INTO "artist_enrichment" VALUES('Mikey Dread', '85fcc6c7-4b54-40dd-bd0e-0df68309acea', 'JM', 1954, '[]', '["reggae", "dub", "classic pop and rock"]', NULL, NULL, '2026-05-24 00:08:31', 1, 'Mikey Dread', '["reggae", "dub", "roots reggae", "jamaica", "roots"]', 'Michael Campbell (1954-2008), better known as Mikey Dread, was a multi-talented Jamaican singer, producer, and broadcaster. During his long career, he brought dub music to the cultural fore in not only Jamaica but internationally, courageously fused dub with punk via work with The Clash, spread a global message of racial unity, and played a seminal role as a forefather of the now popular and very commercial dancehall and even reggaeton styles with popular dub cuts like Roots and Culture.', '115238', '869081', 'https://www.last.fm/music/Mikey+Dread');
