INSERT OR IGNORE INTO "artist_enrichment" VALUES('Minami Deutsch', 'a51ae558-d194-400c-a92f-66b471f92fb7', 'JP', 2014, '[]', '["krautrock", "cosmic", "rock", "psychedelic rock", "minimal"]', 'Minami Deutsch (Japanese: 南ドイツ, Hepburn: Minami Doitsu) are a Japanese krautrock band founded by guitarist and vocalist Kyotaro Miulain in Tokyo in 2014. Their name translates into English as "South German".', 'https://en.wikipedia.org/wiki/Minami_Deutsch', '2026-05-24 00:08:58', 1, 'Minami Deutsch', '["krautrock", "Psychedelic Rock", "japan", "psychedelic", "japanese"]', 'Minami Deutsch (also known as 南ドイツ/Minami Doitsu) are a Japanese krautrock band founded in Shibuya in 2014[/yearplaceformed].   Members: Guitar, Vocals & Synthesizer: Kyotaro Miula Guitar: Yuichi Ushioda (潮田 雄一) Bass: Keita Ise Drums: Kosei Terunuma (照沼 光星)  Former members: Guitar: Riki Hidaka Guitar: Tatsuhiko Rauschenberg  Guitar: Taku Idemoto Bass: Keisuke Ise  Drums: Takuya Nozaki  Drums: Hikari Sakashita Drums: Masahito Goda', '60364', '643932', 'https://www.last.fm/music/Minami+Deutsch');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Lower Plenty', '83ca482a-2c7c-48fa-be73-65a4cfb26e7b', NULL, NULL, '[]', '[]', 'Lower Plenty is a suburb of Melbourne, Victoria, Australia, 16 km north-east from Melbourne''s Central Business District, located within the City of Banyule local government area. Lower Plenty recorded a population of 3,962 at the 2021 census.', 'https://en.wikipedia.org/wiki/Lower_Plenty', '2026-05-23 18:17:03', 1, 'Lower Plenty', NULL, NULL, NULL, NULL, NULL);
