INSERT OR IGNORE INTO "artist_enrichment" VALUES('Le Forte Four', '06a5b17b-5dfe-4ddc-93cd-906530f2b84f', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:09:04', 1, 'Le Forte Four', '["noise", "Avant-Garde", "lafms", "experimental", "nurse with wound list"]', 'Le Forte Four were the earliest group in the collective of avant-garde music anarchists known as the Los Angeles Free Music Society (LAFMS). With their music combining loose experimental improvisation on both conventional instruments and household items with stuff taped off television cartoons or taken from records as well as lo-fi electronics, Le Forte Four were pioneers of sampling, even as their D.I.Y. ethic paved the way for the punk movement a few years later.', '1773', '26549', 'https://www.last.fm/music/Le+Forte+Four');
