INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ben Simmons', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:09:08', 1, 'Ben Simmons', '["All", "ghana", "africa", "world", "spotify"]', 'Benjamin David Simmons (born 20 July 1996) is an Australian professional basketball player for the Brooklyn Nets of the National Basketball Association (NBA). He played college basketball for one season with the LSU Tigers, after which he was named a consensus first-team All-American and the USBWA National Freshman of the Year. Simmons was selected with the first overall pick in the 2016 NBA draft by the Philadelphia 76ers. After sitting out a year due to an injured right foot', '5154', '13744', 'https://www.last.fm/music/Ben+Simmons');
