INSERT OR IGNORE INTO "artist_enrichment" VALUES('Ewah & The Vision Of Paradise', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:09:22', 1, 'Ewah & The Vision Of Paradise', '["post-punk", "synth pop", "dark wave", "art rock"]', 'EWAH & The Vision of Paradise is a band based in nipaluna/Hobart.  They are characterised as post-punk with dark wave undertones.', '529', '3997', 'https://www.last.fm/music/EWAH+&+The+Vision+Of+Paradise');
