INSERT OR IGNORE INTO "artist_enrichment" VALUES('Litanic Mask', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:09:25', 1, 'Litanic Mask', '["electronic", "minimal synth", "pop", "indie", "indietronica"]', 'Forming in early 2011, Litanic Mask is a 3 piece electronic/darkwave/ambient band hailing from Portland, Oregon, made up of Kenna Jean, Mark Evan Burden (Get Hustle, Silentist) and Andrea K. Currently, the band has released one self titled LP, with a second coming soon entitled Vampire. Several songs are available on their official Sound Cloud.', '742', '6012', 'https://www.last.fm/music/Litanic+Mask');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Scattered Order', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:09:25', 1, 'Scattered Order', '["experimental", "post-punk", "minimal electronic", "noise", "new wave"]', 'A noise making band from Sydney, Australia, who began their post punk assault on listeners in 1979. Releases on the M Squared, Volition, Klanggalerie, Ascension and Rather be Vinyl labels throughout a 30 year sonic journey.  Original line-up reformed in 2009 with Mitch Jones and Michael Tee.   Released "SO" CDr in September 2009.   Released "Adjust the terminology" CD in September 2010  In 2010 Shane Fahey joined.  Released "It''s behind you" CDr in May 2011', '3488', '34519', 'https://www.last.fm/music/Scattered+Order');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Au Ras Au Ras', '9adffd40-2f13-41f1-9881-d88086c773e2', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:09:26', 1, 'Au Ras Au Ras', '["twee pop", "Lo-Fi", "twee", "indie", "indie pop"]', 'Tess Brunet writes songs under the moniker Au Ras Au Ras (oh rah oh rah).   Brunet started playing drums in early 2003 while working at S.I.R. studios in New York City as the Accounts Receivable Manger. She primarily writes songs on keys and auto-harp. She is completely self-taught.   Brunet has released music under the name deadboy & the Elephantmen (Fat Possum Records), Animal Electric (self-release), and Generationals (Park The Van). She has also played drums for The Lees, Attack Formation, Lady Bo, Fangtar, Twin Tigers, and One Man Machine.', '1913', '10243', 'https://www.last.fm/music/Au+Ras+Au+Ras');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('The Meters', '851827d6-ae31-4093-a166-1420cac610a4', 'US', 1965, '[]', '["classic pop and rock", "funk"]', 'The Meters (later The Funky Meters) are an American funk band formed in 1965 in New Orleans by Zigaboo Modeliste (drums), George Porter Jr. (bass), Leo Nocentelli (guitar) and Art Neville (keyboards). The band performed and recorded their own music from the late 1960s until 1977 and played an influential role as backing musicians for other artists, including Lee Dorsey, Robert Palmer, Dr. John, and Allen Toussaint. Their original songs "Cissy Strut" and "Look-Ka Py Py" are considered funk classi', 'https://en.wikipedia.org/wiki/The_Meters', '2026-05-24 00:09:26', 1, 'The Meters', '["funk", "soul", "New Orleans", "70s", "groove"]', 'The Meters is an American funk band formed in 1965 by Zigaboo Modeliste (drums), George Porter Jr. (bass), Leo Nocentelli (guitar), and Art Neville (keyboards) in New Orleans. The band performed and recorded their own music from the late 1960s until 1977 and played an influential role as backing musicians for other artists, including Lee Dorsey, Robert Palmer, Dr. John, and Allen Toussaint. Their original songs "Cissy Strut" and "Look-Ka Py Py" are considered funk classics.', '663741', '8087729', 'https://www.last.fm/music/The+Meters');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('→ ↑ →', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:09:27', 1, '→ ↑ →', '["post-punk", "dance-punk", "minimal wave", "australian", "minimal synth"]', '→↑→, (pronounced ''tsk tsk tsk'') and moreoften written (though wrongly) as "Tsk Tsk Tsk" or "Tch Tch Tch", was an Australian experimental musical group formed in Melbourne in 1977 by Philip Brophy, Ralph Traviato and Leigh Parkhill.  Sometimes compared to Andy Warhol''s Factory collective, the group produced experimental music (Brophy on drums or synthesiser), films, videos, and live theatrical performances exploring Brophy''s aesthetic and cultural interests, often on a minimal budget.', '270', '2124', 'https://www.last.fm/music/%E2%86%92+%E2%86%91+%E2%86%92');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Cobbwebs', NULL, NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 00:09:27', 1, 'Cobbwebs', '[]', NULL, '3', '3', 'https://www.last.fm/music/Cobbwebs');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('M.F.S.B. Feat. The Three Degrees', 'f5e66486-4481-4ebf-b1f9-f87ebabf5897', 'US', NULL, '[]', '["philly soul", "session"]', 'MFSB, officially standing for "Mother Father Sister Brother", was a pool of more than 30 studio musicians based at Philadelphia''s Sigma Sound Studios. They worked closely with the production team of Gamble and Huff and producer/arranger Thom Bell, and backed up Harold Melvin & the Blue Notes, the O''Jays, the Stylistics, the Spinners, Wilson Pickett, and Billy Paul.', 'https://en.wikipedia.org/wiki/MFSB', '2026-05-23 18:18:22', 1, 'MFSB', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Mel O’Dubhslaine', '4439c2fd-a754-4f6a-b3a6-791b47726156', 'US', 1925, '[]', '["american", "easy listening soundtracks and musicals", "jazz", "death by stroke", "2008 universal fire victim"]', 'Melvin Howard Tormé (September 13, 1925 – June 5, 1999), nicknamed "The Velvet Fog", was an American musician, singer, composer, arranger, drummer, actor, and author. He composed the music for "The Christmas Song" ("Chestnuts Roasting on an Open Fire") and co-wrote the lyrics with Bob Wells. Tormé won two Grammy Awards and was nominated a total of 14 times.', 'https://en.wikipedia.org/wiki/Mel_Tormé', '2026-05-23 18:18:24', 1, 'Mel Tormé', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('SoliPsiK', '7d461c29-63bd-4fdf-b3f3-1f8d25de1fff', 'AU', 1978, '[]', '["industrial", "noise", "ebm", "synth-pop", "australia", "sydney", "ritual ambient", "synth punk"]', 'SPK  may refer to:', 'https://en.wikipedia.org/wiki/SPK', '2026-05-23 18:18:26', 1, 'SPK', NULL, NULL, NULL, NULL, NULL);
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Link Wray & His Raymen', '211099c8-8e2b-4e96-aa5c-343939754176', 'US', 1958, '[]', '["rockabilly", "blues rock", "garage rock", "rock & roll"]', NULL, NULL, '2026-05-23 23:59:00', 2, 'Link Wray & His Raymen', '[]', NULL, '2883', '20581', 'https://www.last.fm/music/+noredirect/Link+Wray+&+His+Raymen');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('GEN-X', '10465b2d-d76d-4c46-a2c1-be7bd18dc212', NULL, NULL, '[]', '[]', NULL, NULL, '2026-05-24 01:45:57', 1, 'GEN-X', '[]', NULL, '66', '598', 'https://www.last.fm/music/Gen-X');
INSERT OR IGNORE INTO "artist_enrichment" VALUES('Charles Bogert', '11b80336-72fd-4748-b657-43bc3c139e01', 'US', 1908, '[]', '[]', 'Charles Mitchill Bogert (June 4, 1908 – April 10, 1992) was an American herpetologist, and curator of herpetology and researcher for the American Museum of Natural History.', 'https://en.wikipedia.org/wiki/Charles_Bogert', '2026-05-24 02:08:08', 1, 'Charles Bogert', '["field recordings", "frogs"]', 'Charles Mitchill Bogert (June 4, 1908–April 10, 1992) was an American herpetologist, and curator of herpetology and researcher for the American Museum of Natural History.  He is best known for the 1957 album "Sounds of North American Frogs" featuring field recordings and his narration. In 1959 he released "Sounds Of The American Southwest".', '116', '3435', 'https://www.last.fm/music/Charles+Bogert');
CREATE TABLE IF NOT EXISTS album_art (
    album_name TEXT NOT NULL,
    artist_name TEXT NOT NULL,
    mbid TEXT,
    artwork_url TEXT,
    release_year INTEGER,
    release_date TEXT,
    last_fetched TEXT,
    release_group_mbid TEXT,
    canonical_name TEXT,
    PRIMARY KEY (album_name, artist_name)
);
